   * Exact tab ID returned by browser.tabs.open/list. Focus does not select a tool target.
   * @pattern ^tab_[a-f0-9-]{36}$
   */
  tabID: string,
}): Promise<{
  /** @pattern ^tab_[a-f0-9-]{36}$ */
  id: string,
  /** @maxLength 16384 */
  url: string,
  /** @maxLength 2048 */
  title: string,
  loading: boolean,
  /** @maxLength 2048 */
  loadError?: string,
  canGoBack: boolean,
  canGoForward: boolean,
  /** @integer @minimum 0 */
  generation: number,
}> // Stop loading this tab. This does not stop a trace or CPU recording.
  - tools.browser.tabs.list(): Promise<{
  tabs: Array<{
      /** @pattern ^tab_[a-f0-9-]{36}$ */
      id: string,
      /** @maxLength 16384 */
      url: string,
      /** @maxLength 2048 */
      title: string,
      loading: boolean,
      /** @maxLength 2048 */
      loadError?: string,
      canGoBack: boolean,
      canGoForward: boolean,
      /** @integer @minimum 0 */
      generation: number,
    }>,
  focusedTabID: string | null,
}> // List this session's browser tabs and the focused tab. Use returned IDs for all page operations.
  - tools.browser.tabs.open({
  /** @maxLength 2048 */
  url?: string,
  focus?: boolean,
}): Promise<{
  /** @pattern ^tab_[a-f0-9-]{36}$ */
  id: string,
  /** @maxLength 16384 */
  url: string,
  /** @maxLength 2048 */
  title: string,
  loading: boolean,
  /** @maxLength 2048 */
  loadError?: string,
  canGoBack: boolean,
  canGoForward: boolean,
  /** @integer @minimum 0 */
  generation: number,
}> // Open a browser tab, show it in the Review pane, and select it. Defaults to about:blank. Website traffic uses the conn...
