{
  "name": "temple-run-3d",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "description": "Temple Run 3D — a 100-stage endless runner across 20 lost worlds.",
  "scripts": {
    "dev": "vite --host 127.0.0.1 --port 5173",
    "build": "vite build",
    "preview": "vite preview --host 127.0.0.1 --port 4173"
  },
  "dependencies": {
    "three": "0.180.0"
  },
  "devDependencies": {
    "vite": "7.3.7"
  }
}

import { defineConfig } from 'vite'

export default defineConfig({
  server: {
    host: '127.0.0.1',
    port: 5173,
  },
  build: {
    target: 'es2020',
    assetsInlineLimit: 0,
  },
})

import { STAGES_PER_WORLD, getStageConfig, stageKey, WORLDS } from './levels.js'

const KEY = 'temple-run-3d.profile.v1'

export const UPGRADES = {
  magnet: {
    name: 'Relic Magnet',
    icon: 'magnet',
    desc: 'Forge stronger lodestones. Each rank adds +2s to magnet pickups.',
    max: 5,
    costs: [120, 240, 420, 680, 1000],
    effect: (lvl) => `+${lvl * 2}s magnet`,
  },
  heart: {
    name: 'Jade Heart',
    icon: 'heart',
    desc: 'An extra heart lets you survive one more mistake in the ruins.',
    max: 3,
    costs: [200, 420, 760],
    effect: (lvl) => `+${lvl} heart${lvl > 1 ? 's' : ''}`,
  },
  value: {
    name: 'Gilded Touch',
    icon: 'coin',
    desc: 'Every coin you touch is worth a little more. Pure alchemy.',
    max: 5,
    costs: [150, 300, 520, 800, 1200],
    effect: (lvl) => `+${lvl * 8}% coin value`,
  },
}

function defaults() {
  return {
    coins: 0,
    totalCoins: 0,
    next: { world: 1, stage: 1 },
    stars: {},
    bests: {},
    upgrades: { magnet: 0, heart: 0, value: 0 },
    settings: { sound: true, music: true, quality: 'high' },
    stats: { runs: 0, cleared: 0, distance: 0, coinsRun: 0 },
    createdAt: Date.now(),
  }
}

let cache = null

export function loadProfile() {
  if (cache) return cache
  const base = defaults()
  try {
    const raw = localStorage.getItem(KEY)
    if (raw) {
      const parsed = JSON.parse(raw)
      cache = {
        ...base,
        ...parsed,
        next: { ...base.next, ...(parsed.next || {}) },
        upgrades: { ...base.upgrades, ...(parsed.upgrades || {}) },
        settings: { ...base.settings, ...(parsed.settings || {}) },
        stats: { ...base.stats, ...(parsed.stats || {}) },
        stars: parsed.stars || {},
        bests: parsed.bests || {},
      }
    } else {
      cache = base
    }
  } catch {
    cache = base
  }
  return cache
}

export function saveProfile(profile = cache) {
  cache = profile
  try {
    localStorage.setItem(KEY, JSON.stringify(profile))
  } catch {
    /* storage might be unavailable — the run still works */
  }
}

export function resetProfile() {
  cache = defaults()
  saveProfile(cache)
  return cache
}

export function isStageUnlocked(profile, world, stage) {
  if (profile.stars[stageKey(world, stage)] > 0) return true
  return profile.next.world === world && profile.next.stage === stage
}

export function isWorldUnlocked(profile, world) {
  if (world <= profile.next.world) return true
  for (let s = 1; s <= STAGES_PER_WORLD; s++) {
    if (profile.stars[stageKey(world, s)]) return true
  }
  return false
}

export function stageBest(profile, world, stage) {
  return profile.bests[stageKey(world, stage)] || null
}

export function advanceProgress(profile, world, stage) {
  if (world !== profile.next.world || stage !== profile.next.stage) return
  let nWorld = world
  let nStage = stage + 1
  if (nStage > STAGES_PER_WORLD) {
    nWorld = world + 1
    nStage = 1
  }
  if (nWorld > WORLDS.length) {
    profile.next = { world: WORLDS.length, stage: STAGES_PER_WORLD }
    profile.complete = true
  } else {
    profile.next = { world: nWorld, stage: nStage }
  }
}

export function recordRun(profile, { world, stage, distance, coins, score, hits, stars, cleared, time }) {
  const key = stageKey(world, stage)
  const cfg = getStageConfig(world, stage)

  profile.stats.runs += 1
  profile.stats.distance += Math.round(distance)
  profile.stats.coinsRun += coins
  profile.coins += coins
  profile.totalCoins += coins

  const prevBest = profile.bests[key]
  if (!prevBest || score > prevBest.score) {
    profile.bests[key] = { score, distance: Math.round(distance), coins, stars }
  }

  if (cleared) {
    const prevStars = profile.stars[key] || 0
    if (stars > prevStars) profile.stars[key] = stars
    if (prevStars === 0) profile.stats.cleared += 1
    advanceProgress(profile, world, stage)
    profile.lastStage = { world, stage }
  }

  saveProfile(profile)
  return { best: profile.bests[key], newBest: !prevBest || score > prevBest.score, reward: cleared ? cfg.reward : 0 }
}

export function addCoins(profile, amount) {
  profile.coins += amount
  saveProfile(profile)
}

export function totalUpgradeLevel(profile) {
  return Object.values(profile.upgrades).reduce((a, b) => a + b, 0)
}

export function upgradeCost(type, level) {
  const def = UPGRADES[type]
  if (!def || level >= def.max) return Infinity
  return def.costs[level]
}

export function buyUpgrade(profile, type) {
  const def = UPGRADES[type]
  if (!def) return { ok: false, reason: 'unknown' }
  const level = profile.upgrades[type] || 0
  if (level >= def.max) return { ok: false, reason: 'max' }
  const cost = upgradeCost(type, level)
  if (profile.coins < cost) return { ok: false, reason: 'coins' }
  profile.coins -= cost
  profile.upgrades[type] = level + 1
  saveProfile(profile)
  return { ok: true, cost, level: level + 1 }
}

/** Loadout the run should use, derived from the player's profile. */
export function loadout(profile, cfg) {
  return {
    hearts: cfg.hearts + (profile.upgrades.heart || 0),
    magnetTime: cfg.magnetTime + (profile.upgrades.magnet || 0) * 2,
    coinValue: 1 + (profile.upgrades.value || 0) * 0.08,
  }
}

export function nextStageInfo(profile) {
  const { world, stage } = profile.next
  const cfg = getStageConfig(world, stage)
  return {
    ...cfg,
    worldName: WORLDS[world - 1]?.name || 'The Unknown',
    theme: WORLDS[world - 1],
    done: !!profile.complete,
  }
}

// Tiny procedural sound engine — no audio assets required.
export class SoundEngine {
  constructor(settings) {
    this.settings = settings || { sound: true, music: true }
    this.ctx = null
    this.master = null
    this.musicGain = null
    this.sfxGain = null
    this.ambientStarted = false
    this.musicTimer = null
    this.step = 0
    this.ready = false
  }

  unlock() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    this.ctx = new AC()
    this.master = this.ctx.createGain()
    this.master.gain.value = 0.7
    this.master.connect(this.ctx.destination)

    this.sfxGain = this.ctx.createGain()
    this.sfxGain.gain.value = this.settings.sound ? 0.85 : 0
    this.sfxGain.connect(this.master)

    this.musicGain = this.ctx.createGain()
    this.musicGain.gain.value = this.settings.music ? 0.16 : 0
    this.musicGain.connect(this.master)

    this.ready = true
    this.startAmbience()
  }

  setSound(on) {
    this.settings.sound = on
    if (this.sfxGain) this.sfxGain.gain.setTargetAtTime(on ? 0.85 : 0, this.ctx.currentTime, 0.05)
  }

  setMusic(on) {
    this.settings.music = on
    if (this.musicGain) this.musicGain.gain.setTargetAtTime(on ? 0.16 : 0, this.ctx.currentTime, 0.2)
  }

  tone(freq, dur = 0.14, type = 'sine', vol = 0.25, slideTo = null, delay = 0) {
    if (!this.ready || !this.settings.sound) return
    const t0 = this.ctx.currentTime + delay
    const osc = this.ctx.createOscillator()
    const gain = this.ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t0)
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t0 + dur)
    gain.gain.setValueAtTime(0.0001, t0)
    gain.gain.exponentialRampToValueAtTime(vol, t0 + 0.012)
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur)
    osc.connect(gain)
    gain.connect(this.sfxGain)
    osc.start(t0)
    osc.stop(t0 + dur + 0.05)
  }

  noise(dur = 0.2, vol = 0.18, freq = 1200, q = 0.8, delay = 0) {
    if (!this.ready || !this.settings.sound) return
    const t0 = this.ctx.currentTime + delay
    const len = Math.max(1, Math.floor(this.ctx.sampleRate * dur))
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate)
    const data = buf.getChannelData(0)
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1
    const src = this.ctx.createBufferSource()
    src.buffer = buf
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'bandpass'
    filter.frequency.value = freq
    filter.Q.value = q
    const gain = this.ctx.createGain()
    gain.gain.setValueAtTime(vol, t0)
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur)
    src.connect(filter)
    filter.connect(gain)
    gain.connect(this.sfxGain)
    src.start(t0)
  }

  click() {
    this.tone(660, 0.07, 'triangle', 0.14, 880)
  }

  coin(streak = 0) {
    const base = 880 + Math.min(streak, 12) * 28
    this.tone(base, 0.09, 'triangle', 0.13, base * 1.5)
    this.tone(base * 2, 0.06, 'sine', 0.06, base * 2.2, 0.02)
  }

  jump() {
    this.tone(300, 0.18, 'sine', 0.16, 720)
    this.noise(0.12, 0.05, 900, 0.7)
  }

  land() {
    this.noise(0.08, 0.09, 220, 0.9)
    this.tone(110, 0.09, 'sine', 0.12, 70)
  }

  slide() {
    this.noise(0.34, 0.14, 700, 0.55)
    this.tone(240, 0.22, 'sawtooth', 0.04, 110)
  }

  hit() {
    this.tone(140, 0.4, 'sawtooth', 0.18, 45)
    this.noise(0.3, 0.2, 240, 0.6)
    this.tone(90, 0.5, 'sine', 0.22, 30)
  }

  shieldBreak() {
    this.tone(700, 0.25, 'square', 0.09, 180)
    this.noise(0.3, 0.14, 2200, 1.2)
  }

  power() {
    ;[523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.18, 'triangle', 0.1, f, i * 0.06))
  }

  star(i = 0) {
    this.tone(660 * Math.pow(1.26, i), 0.5, 'triangle', 0.16, 660 * Math.pow(1.26, i))
    this.tone(990 * Math.pow(1.26, i), 0.4, 'sine', 0.08, null, 0.04)
  }

  complete() {
    ;[523, 659, 784, 1046, 1318].forEach((f, i) => {
      this.tone(f, 0.5, 'triangle', 0.14, f, i * 0.1)
      this.tone(f / 2, 0.5, 'sine', 0.06, f / 2, i * 0.1)
    })
  }

  fail() {
    ;[392, 330, 262, 196].forEach((f, i) => this.tone(f, 0.5, 'triangle', 0.13, f * 0.98, i * 0.14))
  }

  whoosh() {
    this.noise(0.2, 0.07, 500, 0.5)
  }

  // ── ambient bed: low drone + sparse pentatonic flute ──
  startAmbience() {
    if (this.ambientStarted || !this.ctx) return
    this.ambientStarted = true

    const droneGain = this.ctx.createGain()
    droneGain.gain.value = 0.25
    droneGain.connect(this.musicGain)

    const filter = this.ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = 320
    filter.Q.value = 2
    filter.connect(droneGain)

    ;[55, 82.5, 110].forEach((f, i) => {
      const osc = this.ctx.createOscillator()
      osc.type = i === 2 ? 'triangle' : 'sine'
      osc.frequency.value = f
      osc.detune.value = i * 4 - 4
      const g = this.ctx.createGain()
      g.gain.value = 0.16 / (i + 1)
      osc.connect(g)
      g.connect(filter)
      osc.start()
    })

    // soft wind
    const len = this.ctx.sampleRate * 4
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate)
    const data = buf.getChannelData(0)
    for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * 0.5
    const src = this.ctx.createBufferSource()
    src.buffer = buf
    src.loop = true
    const windFilter = this.ctx.createBiquadFilter()
    windFilter.type = 'bandpass'
    windFilter.frequency.value = 500
    windFilter.Q.value = 0.6
    const windGain = this.ctx.createGain()
    windGain.gain.value = 0.035
    src.connect(windFilter)
    windFilter.connect(windGain)
    windGain.connect(this.musicGain)
    src.start()

    // sparse flute notes every few seconds
    const scale = [392, 440, 523, 587, 659, 784]
    const notes = [0, 2, 4, 5, 4, 2, 1, 3]
    this.musicTimer = setInterval(() => {
      if (!this.settings.music || !this.ctx || this.ctx.state !== 'running') return
      this.step = (this.step + 1) % notes.length
      const f = scale[notes[this.step]]
      const t0 = this.ctx.currentTime
      const osc = this.ctx.createOscillator()
      const g = this.ctx.createGain()
      osc.type = 'sine'
      osc.frequency.value = f
      g.gain.setValueAtTime(0.0001, t0)
      g.gain.exponentialRampToValueAtTime(0.055, t0 + 0.08)
      g.gain.exponentialRampToValueAtTime(0.0001, t0 + 1.8)
      osc.connect(g)
      g.connect(this.musicGain)
      osc.start(t0)
      osc.stop(t0 + 2)
    }, 3400)
  }
}

import * as THREE from 'three'

// ─────────────────────────────────────────────────────────────
//  TEMPLE RUN 3D — game engine
//  Three.js endless-runner: 3 lanes, jump, slide, coins, relics.
// ─────────────────────────────────────────────────────────────

export const LANE_X = [-2.35, 0, 2.35]
const CHUNK_LEN = 32
const CHUNK_COUNT = 7
const PLAYER_H = 1.92
const SLIDE_H = 0.8
const GRAVITY = -58
const JUMP_V = 16.6
const START_Z = 20

const clamp = (v, a, b) => Math.max(a, Math.min(b, v))
const lerp = (a, b, t) => a + (b - a) * t
const damp = (a, b, l, dt) => lerp(a, b, 1 - Math.exp(-l * dt))
const rand = (a, b) => a + Math.random() * (b - a)
const randInt = (a, b) => Math.floor(rand(a, b + 1))
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)]
const shuffle = (arr) => [...arr].sort(() => Math.random() - 0.5)
const color = (hex) => new THREE.Color(hex)

function makeGlowTexture(inner = 'rgba(255,255,255,1)', outer = 'rgba(255,255,255,0)') {
  const c = document.createElement('canvas')
  c.width = c.height = 128
  const ctx = c.getContext('2d')
  const g = ctx.createRadialGradient(64, 64, 2, 64, 64, 62)
  g.addColorStop(0, inner)
  g.addColorStop(0.35, 'rgba(255,255,255,0.45)')
  g.addColorStop(1, outer)
  ctx.fillStyle = g
  ctx.fillRect(0, 0, 128, 128)
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  return tex
}

function makeStoneTexture(theme) {
  const size = 512
  const c = document.createElement('canvas')
  c.width = c.height = size
  const ctx = c.getContext('2d')
  const base = color(theme.stone)
  const dark = color(theme.stoneDark)
  const moss = color(theme.foliage)

  ctx.fillStyle = `#${base.getHexString()}`
  ctx.fillRect(0, 0, size, size)

  // stone blocks
  const cols = 4
  const rows = 8
  const bw = size / cols
  const bh = size / rows
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const shade = rand(-0.1, 0.12)
      const col = base.clone().offsetHSL(0, 0, shade)
      ctx.fillStyle = `#${col.getHexString()}`
      ctx.fillRect(x * bw + 3, y * bh + 3, bw - 6, bh - 6)
      // worn bevel
      ctx.strokeStyle = `rgba(255,255,255,${rand(0.03, 0.09)})`
      ctx.lineWidth = 2
      ctx.beginPath()
      ctx.moveTo(x * bw + 4, y * bh + bh - 4)
      ctx.lineTo(x * bw + 4, y * bh + 4)
      ctx.lineTo(x * bw + bw - 4, y * bh + 4)
      ctx.stroke()
    }
  }

  // grout
  ctx.strokeStyle = `#${dark.getHexString()}`
  ctx.globalAlpha = 0.55
  ctx.lineWidth = 5
  for (let y = 0; y <= rows; y++) {
    ctx.beginPath()
    ctx.moveTo(0, y * bh)
    ctx.lineTo(size, y * bh)
    ctx.stroke()
  }
  for (let x = 0; x <= cols; x++) {
    ctx.beginPath()
    ctx.moveTo(x * bw, 0)
    ctx.lineTo(x * bw, size)
    ctx.stroke()
  }
  ctx.globalAlpha = 1

  // speckle
  for (let i = 0; i < 2600; i++) {
    const v = Math.random()
    ctx.fillStyle = v > 0.5 ? `rgba(255,255,255,${Math.random() * 0.07})` : `rgba(0,0,0,${Math.random() * 0.12})`
    const r = Math.random() * 2.4
    ctx.fillRect(Math.random() * size, Math.random() * size, r, r)
  }

  // cracks
  for (let i = 0; i < 7; i++) {
    ctx.strokeStyle = `rgba(0,0,0,${rand(0.12, 0.28)})`
    ctx.lineWidth = rand(1, 2.5)
    let x = Math.random() * size
    let y = Math.random() * size
    ctx.beginPath()
    ctx.moveTo(x, y)
    for (let s = 0; s < 6; s++) {
      x += rand(-26, 26)
      y += rand(12, 34)
      ctx.lineTo(x, y)
    }
    ctx.stroke()
  }

  // moss creeping at edges
  ctx.fillStyle = `#${moss.getHexString()}`
  for (let i = 0; i < 90; i++) {
    ctx.globalAlpha = rand(0.05, 0.22)
    const r = rand(4, 22)
    ctx.beginPath()
    ctx.arc(Math.random() < 0.5 ? rand(0, 50) : rand(size - 50, size), Math.random() * size, r, 0, Math.PI * 2)
    ctx.fill()
  }
  ctx.globalAlpha = 1

  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping
  tex.repeat.set(2, 5)
  tex.anisotropy = 4
  return tex
}

export class TempleGame {
  constructor(canvas, callbacks = {}) {
    this.canvas = canvas
    this.cb = callbacks
    this.state = 'attract'
    this.theme = null
    this.time = 0
    this.lastHud = 0
    this.active = []
    this.pool = { coin: [], hurdle: [], beam: [], blocker: [], magnet: [], shield: [] }
    this.chunks = []
    this.flames = []
    this.powerups = 0
    this.gate = null
    this.finishedNotified = false

    this.initRenderer()
    this.initScene()
    this.initMaterials()
    this.initTrack()
    this.initPlayer()
    this.initEffects()
    this.bindInput()
    this.loop = this.loop.bind(this)
    this.clock = new THREE.Clock()
    this.resizeObserver = new ResizeObserver(() => this.resize())
    this.resizeObserver.observe(document.body)
    window.addEventListener('resize', () => this.resize())
    this.resize()
    requestAnimationFrame(this.loop)
  }

  // ── setup ──────────────────────────────────────────────────
  initRenderer() {
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      antialias: true,
      powerPreference: 'high-performance',
    })
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75))
    this.renderer.shadowMap.enabled = true
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping
    this.renderer.toneMappingExposure = 1.02
    this.renderer.outputColorSpace = THREE.SRGBColorSpace
    this.quality = 'high'
  }

  initScene() {
    this.scene = new THREE.Scene()
    this.scene.fog = new THREE.Fog(0xc9a878, 46, 168)

    this.camera = new THREE.PerspectiveCamera(60, 1, 0.1, 900)
    this.camera.position.set(0, 4.7, 9.6)
    this.camera.lookAt(0, 1.7, -16)
    this.camX = 0
    this.camY = 4.7
    this.fov = 60
    this.shake = 0

    // sky dome
    this.skyMat = new THREE.ShaderMaterial({
      uniforms: {
        topColor: { value: new THREE.Color('#1d4e74') },
        bottomColor: { value: new THREE.Color('#ffc46b') },
        sunDir: { value: new THREE.Vector3(0.5, 0.5, -0.7).normalize() },
      },
      vertexShader: /* glsl */ `
        varying vec3 vPos;
        void main() {
          vPos = position;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: /* glsl */ `
        uniform vec3 topColor;
        uniform vec3 bottomColor;
        uniform vec3 sunDir;
        varying vec3 vPos;
        void main() {
          vec3 dir = normalize(vPos);
          float h = clamp(dir.y * 0.5 + 0.5, 0.0, 1.0);
          vec3 c = mix(bottomColor, topColor, pow(h, 1.15));
          float glow = pow(max(dot(dir, normalize(sunDir)), 0.0), 8.0);
          c += vec3(1.0, 0.65, 0.3) * glow * 0.35;
          gl_FragColor = vec4(c, 1.0);
        }
      `,
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
    })
    const sky = new THREE.Mesh(new THREE.SphereGeometry(600, 32, 20), this.skyMat)
    sky.renderOrder = -10
    this.scene.add(sky)

    this.glowTex = makeGlowTexture()

    // sun
    this.sunSprite = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: this.glowTex,
        color: 0xffd28a,
        transparent: true,
        opacity: 0.95,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        fog: false,
      }),
    )
    this.sunSprite.scale.set(150, 150, 1)
    this.sunSprite.position.set(130, 95, -330)
    this.scene.add(this.sunSprite)

    // terrain apron
    const apron = new THREE.Mesh(
      new THREE.PlaneGeometry(700, 700),
      new THREE.MeshStandardMaterial({ color: 0x6b573f, roughness: 1, metalness: 0 }),
    )
    apron.rotation.x = -Math.PI / 2
    apron.position.y = -1.6
    apron.receiveShadow = true
    this.scene.add(apron)
    this.apron = apron

    // far mountains + temple silhouette
    this.bgGroup = new THREE.Group()
    this.bgMats = []
    const mountainColors = [0x6f604d, 0x5a4d3d, 0x4a3f33]
    for (let i = 0; i < 16; i++) {
      const a = (i / 16) * Math.PI * 2
      const r = rand(330, 430)
      const h = rand(55, 130)
      const mat = new THREE.MeshBasicMaterial({
        color: mountainColors[i % 3],
        fog: false,
        transparent: true,
        opacity: 0.85,
      })
      this.bgMats.push(mat)
      const m = new THREE.Mesh(new THREE.ConeGeometry(rand(60, 100), h, 5), mat)
      m.position.set(Math.cos(a) * r, h / 2 - 30, Math.sin(a) * r - 40)
      m.rotation.y = rand(0, Math.PI)
      this.bgGroup.add(m)
    }

    const templeMat = new THREE.MeshBasicMaterial({ color: 0x3c3026, fog: false, transparent: true, opacity: 0.96 })
    this.bgMats.push(templeMat)
    const temple = new THREE.Group()
    const steps = [
      [220, 26, 60],
      [176, 26, 52],
      [136, 26, 44],
      [100, 26, 36],
      [68, 26, 28],
      [40, 30, 24],
    ]
    let yy = -34
    steps.forEach(([w, h, d], i) => {
      const box = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), templeMat)
      box.position.y = yy + h / 2
      yy += h
      temple.add(box)
      if (i === steps.length - 1) {
        const cap = new THREE.Mesh(new THREE.ConeGeometry(w * 0.75, h * 1.6, 4), templeMat)
        cap.position.y = yy - 30 + h
        cap.rotation.y = Math.PI / 4
        temple.add(cap)
      }
    })
    const door = new THREE.Mesh(
      new THREE.PlaneGeometry(12, 20),
      new THREE.MeshBasicMaterial({ color: 0xffc45c, fog: false, transparent: true, opacity: 0.55 }),
    )
    door.position.set(0, -34 + 25, 31)
    temple.add(door)
    temple.position.set(0, 0, -395)
    this.temple = temple
    this.bgGroup.add(temple)
    this.scene.add(this.bgGroup)

    // clouds
    this.clouds = []
    for (let i = 0; i < 7; i++) {
      const s = new THREE.Sprite(
        new THREE.SpriteMaterial({
          map: this.glowTex,
          color: 0xffffff,
          transparent: true,
          opacity: rand(0.05, 0.13),
          depthWrite: false,
          fog: false,
        }),
      )
      s.scale.set(rand(90, 190), rand(24, 44), 1)
      s.position.set(rand(-260, 260), rand(45, 105), rand(-380, -220))
      this.scene.add(s)
      this.clouds.push(s)
    }

    // lights
    this.hemi = new THREE.HemisphereLight(0xbfe6ff, 0x5b4630, 1.05)
    this.scene.add(this.hemi)

    this.sunLight = new THREE.DirectionalLight(0xfff0cf, 2.4)
    this.sunLight.position.set(14, 24, 10)
    this.sunLight.castShadow = true
    this.sunLight.shadow.mapSize.set(2048, 2048)
    this.sunLight.shadow.camera.left = -20
    this.sunLight.shadow.camera.right = 20
    this.sunLight.shadow.camera.top = 24
    this.sunLight.shadow.camera.bottom = -10
    this.sunLight.shadow.camera.near = 1
    this.sunLight.shadow.camera.far = 80
    this.sunLight.shadow.bias = -0.0004
    this.sunLight.shadow.normalBias = 0.02
    this.sunLight.target.position.set(0, 0, -6)
    this.scene.add(this.sunLight)
    this.scene.add(this.sunLight.target)

    this.accentLight = new THREE.PointLight(0xffc45c, 26, 42, 1.8)
    this.accentLight.position.set(0, 4.5, -8)
    this.scene.add(this.accentLight)

    this.rimLight = new THREE.DirectionalLight(0x9fd8ff, 0.7)
    this.rimLight.position.set(-10, 8, -18)
    this.scene.add(this.rimLight)

    this.staticGroup = new THREE.Group()
    this.dynamicGroup = new THREE.Group()
    this.scene.add(this.staticGroup)
    this.scene.add(this.dynamicGroup)
  }

  initMaterials() {
    this.materials = {
      floor: new THREE.MeshStandardMaterial({ color: 0xa9835b, roughness: 0.94, metalness: 0.06 }),
      stone: new THREE.MeshStandardMaterial({ color: 0x9a7a55, roughness: 0.9, metalness: 0.04 }),
      stoneDark: new THREE.MeshStandardMaterial({ color: 0x6b4f34, roughness: 0.95, metalness: 0.03 }),
      gold: new THREE.MeshStandardMaterial({
        color: 0xffc94d,
        roughness: 0.34,
        metalness: 0.85,
        emissive: 0x4a2c00,
        emissiveIntensity: 0.5,
      }),
      wood: new THREE.MeshStandardMaterial({ color: 0x4d3520, roughness: 0.95 }),
      foliage: new THREE.MeshStandardMaterial({ color: 0x3f7d3a, roughness: 0.9 }),
      foliage2: new THREE.MeshStandardMaterial({ color: 0x2e5e2c, roughness: 0.9 }),
      banner: new THREE.MeshStandardMaterial({
        color: 0xff7a3c,
        roughness: 0.8,
        side: THREE.DoubleSide,
        emissive: 0x4a1200,
        emissiveIntensity: 0.25,
      }),
      flame: new THREE.MeshBasicMaterial({ color: 0xffb347 }),
      glow: new THREE.SpriteMaterial({
        map: this.glowTex,
        color: 0xffc45c,
        transparent: true,
        opacity: 0.55,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        fog: false,
      }),
    }

    this.coinMat = new THREE.MeshStandardMaterial({
      color: 0xffcf4a,
      roughness: 0.24,
      metalness: 0.9,
      emissive: 0xff9a00,
      emissiveIntensity: 0.42,
    })
    this.magnetMat = new THREE.MeshStandardMaterial({
      color: 0xb07bff,
      roughness: 0.3,
      metalness: 0.6,
      emissive: 0x7a2bff,
      emissiveIntensity: 1.2,
    })
    this.shieldMat = new THREE.MeshStandardMaterial({
      color: 0x59f2ff,
      roughness: 0.2,
      metalness: 0.4,
      emissive: 0x0f9fb8,
      emissiveIntensity: 1.1,
      transparent: true,
      opacity: 0.9,
    })
  }

  // ── theme ──────────────────────────────────────────────────
  setTheme(theme) {
    if (!theme) return
    if (this.theme && this.theme.name === theme.name) return
    this.theme = theme
    const fog = color(theme.fog)
    this.scene.fog.color = fog
    this.scene.fog.near = 44
    this.scene.fog.far = 168
    if (this.renderer) this.renderer.setClearColor(fog)

    this.skyMat.uniforms.topColor.value = color(theme.sky[0])
    this.skyMat.uniforms.bottomColor.value = color(theme.sky[1])
    this.sunSprite.material.color = color(theme.accent)
    this.apron.material.color = fog.clone().multiplyScalar(0.72)

    this.hemi.color = color(theme.sky[1]).lerp(new THREE.Color('#ffffff'), 0.35)
    this.hemi.groundColor = color(theme.stoneDark).lerp(new THREE.Color('#000000'), 0.2)
    this.hemi.intensity = theme.light
    this.sunLight.color = color(theme.accent).lerp(new THREE.Color('#ffffff'), 0.65)
    this.sunLight.intensity = theme.sun
    this.accentLight.color = color(theme.accent)
    this.rimLight.color = color(theme.accent2)

    this.materials.floor.color = color(theme.stone)
    this.materials.stone.color = color(theme.stone).offsetHSL(0, -0.02, 0.03)
    this.materials.stoneDark.color = color(theme.stoneDark)
    this.materials.gold.color = color(theme.accent)
    this.materials.gold.emissive = color(theme.accent2).multiplyScalar(0.16)
    this.materials.wood.color = color(theme.stoneDark).offsetHSL(0.02, 0.05, -0.04)
    this.materials.foliage.color = color(theme.foliage)
    this.materials.foliage2.color = color(theme.foliage).offsetHSL(0, 0, -0.05)
    this.materials.banner.color = color(theme.accent2)
    this.materials.flame.color = color(theme.flame)
    this.materials.glow.color = color(theme.flame)

    // floor texture
    if (this.materials.floor.map) this.materials.floor.map.dispose()
    this.materials.floor.map = makeStoneTexture(theme)
    this.materials.floor.needsUpdate = true

    // distant silhouettes
    const silhouette = fog.clone().lerp(color(theme.sky[0]), 0.28)
    this.bgMats.forEach((m, i) => {
      m.color = silhouette.clone().offsetHSL(0, 0, -0.05 * (i % 3))
    })
    this.temple.traverse((o) => {
      if (o.isMesh && o !== this.temple.children[this.temple.children.length - 1]) {
        // keep the glowing doorway as-is
      }
    })

    this.bgGroup.children.forEach((o) => {
      if (o.isMesh) o.material.color = silhouette
    })

    this.sunSprite.material.color = color(theme.accent)
    this.clouds.forEach((c) => (c.material.color = color(theme.sky[1])))
    this.apron.material.color = fog.clone().multiplyScalar(0.62)

    this.coinMat.emissive = color(theme.accent)
    this.coinMat.color = color(theme.accent).lerp(new THREE.Color('#fff6c9'), 0.45)
    this.magnetMat.color = color(theme.accent2)
    this.magnetMat.emissive = color(theme.accent2).multiplyScalar(0.7)

    this.materials.glow.needsUpdate = true
    this.materials.floor.needsUpdate = true

    this.buildTrack()
    this.rebuildFinishGate()
  }

  setQuality(quality) {
    this.quality = quality
    const ratio = quality === 'high' ? 1.75 : quality === 'low' ? 1 : 1.35
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, ratio))
    const shadows = quality !== 'low'
    this.renderer.shadowMap.enabled = shadows
    this.sunLight.castShadow = shadows
    if (shadows) {
      const size = quality === 'high' ? 2048 : 1024
      this.sunLight.shadow.mapSize.set(size, size)
      this.sunLight.shadow.map?.dispose()
      this.sunLight.shadow.map = null
    }
    this.materials.floor.needsUpdate = true
    this.resize()
  }

  // ── track chunks ───────────────────────────────────────────
  initTrack() {
    this.floorGeo = new THREE.BoxGeometry(10.6, 0.7, CHUNK_LEN)
    this.sideGeo = new THREE.BoxGeometry(3.2, 0.5, CHUNK_LEN)
    this.laneGeo = new THREE.BoxGeometry(0.05, 0.02, CHUNK_LEN)
    this.pillarGeo = new THREE.CylinderGeometry(0.42, 0.54, 1, 7)
    this.capGeo = new THREE.BoxGeometry(1.2, 0.26, 1.2)
    this.postGeo = new THREE.CylinderGeometry(0.09, 0.12, 1, 6)
    this.trunkGeo = new THREE.CylinderGeometry(0.16, 0.26, 1, 6)
    this.leafGeo = new THREE.ConeGeometry(1, 1, 6)

    for (let i = 0; i < CHUNK_COUNT; i++) {
      const g = new THREE.Group()
      g.userData.index = i
      this.staticGroup.add(g)
      this.chunks.push(g)
    }
    this.buildTrack()
  }

  buildTrack() {
    this.chunks.forEach((g, i) => {
      g.clear()
      g.position.set(0, 0, START_Z - i * CHUNK_LEN)
      this.buildChunk(g, i)
    })
  }

  buildChunk(g, idx) {
    const M = this.materials
    const floor = new THREE.Mesh(this.floorGeo, M.floor)
    floor.position.y = -0.35
    floor.receiveShadow = true
    g.add(floor)

    // side ledges
    const sideL = new THREE.Mesh(this.sideGeo, M.stoneDark)
    sideL.position.set(-6.8, -0.5, 0)
    sideL.receiveShadow = true
    g.add(sideL)
    const sideR = sideL.clone()
    sideR.position.x = 6.8
    g.add(sideR)

    // gilded curb
    const curbGeo = new THREE.BoxGeometry(0.24, 0.16, CHUNK_LEN)
    for (const x of [-5.15, 5.15]) {
      const curb = new THREE.Mesh(curbGeo, M.gold)
      curb.position.set(x, 0.08, 0)
      curb.receiveShadow = true
      g.add(curb)
    }

    // lane guides
    for (const x of [-1.175, 1.175]) {
      const lane = new THREE.Mesh(this.laneGeo, M.stoneDark)
      lane.position.set(x, 0.005, 0)
      g.add(lane)
    }

    // pillars & torches
    const dashPattern = [1, 1, 0, 1, 0, 1, 1, 0]
    for (let s = 0; s < 4; s++) {
      const z = -CHUNK_LEN / 2 + 4 + s * 8
      for (const side of [-1, 1]) {
        if (dashPattern[(s + idx + (side > 0 ? 3 : 0)) % dashPattern.length] === 0) continue
        const broken = Math.random() < 0.22
        const h = broken ? rand(1.2, 2.4) : rand(4.2, 6.4)
        const px = side * rand(6.3, 7.1)
        const p = new THREE.Mesh(this.pillarGeo, M.stone)
        p.scale.y = h
        p.position.set(px, h / 2 - 0.2, z + rand(-0.5, 0.5))
        p.rotation.y = rand(0, Math.PI)
        p.castShadow = true
        p.receiveShadow = true
        g.add(p)
        const cap = new THREE.Mesh(this.capGeo, M.stoneDark)
        cap.position.set(px, h - 0.2, p.position.z)
        cap.rotation.y = p.rotation.y
        cap.scale.setScalar(rand(0.85, 1.2))
        cap.castShadow = true
        g.add(cap)
        if (broken) continue

        // torch every other column
        if ((s + idx) % 2 === 0) {
          const post = new THREE.Mesh(this.postGeo, M.wood)
          post.scale.y = 0.9
          post.position.set(px - side * 0.75, 2.2, p.position.z)
          g.add(post)
          const bowl = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.14, 0.24, 8), M.gold)
          bowl.position.set(post.position.x, 2.72, post.position.z)
          g.add(bowl)
          const flame = new THREE.Mesh(new THREE.IcosahedronGeometry(0.23, 0), M.flame)
          flame.position.set(post.position.x, 2.98, post.position.z)
          flame.scale.set(1, 1.5, 1)
          flame.userData.phase = rand(0, 10)
          g.add(flame)
          this.flames.push(flame)
          const glow = new THREE.Sprite(M.glow.clone())
          glow.position.set(flame.position.x, 3.02, flame.position.z)
          glow.scale.set(2.6, 2.6, 1)
          g.add(glow)
        }
      }
    }

    // arches
    if (idx % 3 === 1 || Math.random() < 0.25) {
      const z = -CHUNK_LEN / 2 + rand(8, 24)
      const h = 6.4
      for (const side of [-1, 1]) {
        const p = new THREE.Mesh(this.pillarGeo, M.stoneDark)
        p.scale.y = h
        p.position.set(side * 5.6, h / 2 - 0.2, z)
        p.castShadow = true
        g.add(p)
      }
      const lintel = new THREE.Mesh(new THREE.BoxGeometry(12.4, 0.8, 1.1), M.stone)
      lintel.position.set(0, h - 0.2, z)
      lintel.castShadow = true
      g.add(lintel)
      const trim = new THREE.Mesh(new THREE.BoxGeometry(12.6, 0.14, 1.24), M.gold)
      trim.position.set(0, h - 0.66, z)
      g.add(trim)

      // hanging vines / banners
      for (let v = 0; v < 4; v++) {
        if (Math.random() < 0.5) continue
        const hh = rand(0.8, 2.6)
        const vine = new THREE.Mesh(new THREE.BoxGeometry(0.06, hh, 0.06), M.foliage2)
        vine.position.set(rand(-4.6, 4.6), h - 0.6 - hh / 2, z + 0.2)
        g.add(vine)
      }
      const banner = new THREE.Mesh(new THREE.PlaneGeometry(1.1, 2.4), M.banner)
      banner.position.set(rand(-3.6, 3.6), h - 1.9, z + 0.5)
      g.add(banner)
    }

    // trees / rocks outside the track
    for (let t = 0; t < 3; t++) {
      const side = Math.random() < 0.5 ? -1 : 1
      const x = side * rand(8.6, 13.5)
      const z = rand(-CHUNK_LEN / 2 + 2, CHUNK_LEN / 2 - 2)
      const trunkH = rand(2.4, 4.6)
      const trunk = new THREE.Mesh(this.trunkGeo, M.wood)
      trunk.scale.y = trunkH
      trunk.position.set(x, trunkH / 2 - 1.2, z)
      trunk.castShadow = true
      g.add(trunk)
      const leaves = new THREE.Mesh(this.leafGeo, Math.random() < 0.5 ? M.foliage : M.foliage2)
      leaves.scale.set(rand(1.4, 2.4), rand(2.4, 4.2), rand(1.4, 2.4))
      leaves.position.set(x + rand(-0.4, 0.4), trunkH - 0.4, z)
      leaves.rotation.y = rand(0, Math.PI)
      leaves.castShadow = true
      g.add(leaves)
    }

    // scattered rubble
    for (let r = 0; r < 4; r++) {
      const rub = new THREE.Mesh(new THREE.BoxGeometry(rand(0.3, 0.8), rand(0.2, 0.5), rand(0.3, 0.9)), M.stoneDark)
      const side = Math.random() < 0.5 ? -1 : 1
      rub.position.set(side * rand(6.1, 9.6), 0.05, rand(-14, 14))
      rub.rotation.y = rand(0, Math.PI)
      rub.castShadow = true
      g.add(rub)
    }
  }

