  initEffects() {
    // floating dust
    const count = 260
    const pos = new Float32Array(count * 3)
    const seeds = new Float32Array(count)
    for (let i = 0; i < count; i++) {
      pos[i * 3] = rand(-20, 20)
      pos[i * 3 + 1] = rand(0.2, 12)
      pos[i * 3 + 2] = rand(-120, 12)
      seeds[i] = rand(0, Math.PI * 2)
    }
    this.dustSeeds = seeds
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    this.dust = new THREE.Points(
      geo,
      new THREE.PointsMaterial({
        color: 0xffe6b0,
        size: 0.16,
        map: this.glowTex,
        transparent: true,
        opacity: 0.5,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        sizeAttenuation: true,
      }),
    )
    this.dust.frustumCulled = false
    this.scene.add(this.dust)
  }

  bindInput() {
    this.onKey = (e) => {
      if (this.state !== 'running' && this.state !== 'ready') return
      const k = e.key.toLowerCase()
      if (['arrowleft', 'a'].includes(k)) {
        this.moveLane(-1)
        e.preventDefault()
      } else if (['arrowright', 'd'].includes(k)) {
        this.moveLane(1)
        e.preventDefault()
      } else if (['arrowup', 'w', ' '].includes(k)) {
        this.jump()
        e.preventDefault()
      } else if (['arrowdown', 's'].includes(k)) {
        this.slide()
        e.preventDefault()
      } else if (k === 'escape' || k === 'p') {
        this.cb.onPauseRequest?.()
      }
    }
    window.addEventListener('keydown', this.onKey)
  }

  // ── run lifecycle ──────────────────────────────────────────
  enterAttract(theme) {
    if (theme) this.setTheme(theme)
    this.clearDynamic()
    this.resetTrackPosition()
    this.state = 'attract'
    this.speed = 4.2
    this.attractT = 0
    this.player.position.set(0, 0, 0)
    this.playerX = 0
    this.laneIndex = 1
    this.playerY = 0
    this.sliding = 0
    this.slideAmt = 0
    this.rig.rotation.set(0, 0, 0)
    this.shieldMesh.visible = false
    this.magnetRingGroup.visible = false
    this.magnetTime = 0
    this.shield = false
    this.finishGateZ = null
    if (this.gate) this.gate.visible = false
  }

  resetTrackPosition() {
    this.chunks.forEach((g, i) => {
      g.position.z = START_Z - i * CHUNK_LEN
    })
  }

  start({ theme, config, loadout, worldName }) {
    if (theme) this.setTheme(theme)
    this.clearDynamic()
    this.resetTrackPosition()

    this.cfg = config
    this.worldName = worldName || ''
    this.state = 'ready'
    this.readyT = 0
    this.readyTime = 0.95
    this.distance = 0
    this.elapsed = 0
    this.coinScore = 0
    this.coinCount = 0
    this.hits = 0
    this.score = 0
    this.speed = config.startSpeed * 0.45
    this.targetSpeed = config.startSpeed
    this.finishGateZ = null
    this.gateSpawned = false
    this.finishedNotified = false

    this.maxHearts = loadout.hearts
    this.hearts = loadout.hearts
    this.magnetMax = loadout.magnetTime
    this.magnetTime = 0
    this.shield = false
    this.coinValue = loadout.coinValue || 1
    this.invuln = 0
    this.stumble = 0
    this.playerY = 0
    this.vy = 0
    this.grounded = true
    this.sliding = 0
    this.slideAmt = 0
    this.laneIndex = 1
    this.playerX = 0
    this.player.position.set(0, 0, 0)
    this.player.rotation.set(0, 0, 0)
    this.rig.rotation.set(0, 0, 0)
    this.rig.position.set(0, 0, 0)
    this.player.visible = true
    this.shake = 0
    this.camX = 0
    this.hitFlash = 0
    this.flyText = null
    this.shieldMesh.visible = false
    this.magnetRingGroup.visible = false
    this.spawnClock = 0
    this.lastSpawnZ = -58
    this.rowCounter = 0
    this.spawnedPowerups = 0
    this.activeCoinsMax = 0
    this.stageCoinsPossible = 0
    this.gateArmed = false
    if (this.gate) this.gate.visible = false
    this.laneCooldown = 0
    this.emitHud(true)
  }

  pause() {
    if (this.state === 'running' || this.state === 'ready') {
      this.prevState = this.state
      this.state = 'paused'
    }
  }

  resume() {
    if (this.state === 'paused') {
      this.state = this.prevState || 'running'
      this.clock.getDelta()
    }
  }

  quit() {
    this.state = 'attract'
    this.clearDynamic()
    this.resetTrackPosition()
    if (this.gate) this.gate.visible = false
  }

  clearDynamic() {
    for (const item of this.active) {
      item.mesh.visible = false
      this.pool[item.kind]?.push(item.mesh)
    }
    this.active.length = 0
    if (this.gate) this.gate.visible = false
    this.finishGateZ = null
  }

  // ── dynamic object pools ───────────────────────────────────
  createCoinMesh() {
    const g = new THREE.Group()
    const disc = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.34, 0.08, 18), this.coinMat)
    disc.rotation.x = Math.PI / 2
    disc.castShadow = true
    g.add(disc)
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.33, 0.045, 6, 18), this.coinMat)
    g.add(ring)
    const glow = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: this.glowTex,
        color: 0xffc94d,
        transparent: true,
        opacity: 0.5,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      }),
    )
    glow.scale.set(1.5, 1.5, 1)
    g.add(glow)
    return g
  }

  createHurdleMesh() {
    const g = new THREE.Group()
    const base = new THREE.Mesh(new THREE.BoxGeometry(1.85, 0.78, 0.72), this.materials.stoneDark)
    base.position.y = 0.39
    base.castShadow = true
    base.receiveShadow = true
    g.add(base)
    const top = new THREE.Mesh(new THREE.BoxGeometry(1.95, 0.14, 0.82), this.materials.gold)
    top.position.y = 0.85
    top.castShadow = true
    g.add(top)
    for (const s of [-1, 1]) {
      const foot = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.18, 0.9), this.materials.stone)
      foot.position.set(s * 0.6, 0.09, 0)
      g.add(foot)
    }
    g.userData.collider = { hx: 0.95, hz: 0.42, y0: 0, y1: 0.94 }
