  }

  createBlockerMesh() {
    const g = new THREE.Group()
    const base = new THREE.Mesh(new THREE.BoxGeometry(1.9, 0.4, 1.25), this.materials.stoneDark)
    base.position.y = 0.2
    base.castShadow = true
    base.receiveShadow = true
    g.add(base)
    const body = new THREE.Mesh(new THREE.BoxGeometry(1.62, 2.0, 1.0), this.materials.stone)
    body.position.y = 1.4
    body.castShadow = true
    body.receiveShadow = true
    g.add(body)
    const chestTrim = new THREE.Mesh(new THREE.BoxGeometry(1.68, 0.16, 1.06), this.materials.gold)
    chestTrim.position.y = 1.42
    g.add(chestTrim)
