  createMagnetMesh() {
    const g = new THREE.Group()
    const torus = new THREE.Mesh(new THREE.TorusGeometry(0.3, 0.11, 8, 18, Math.PI * 1.25), this.magnetMat)
    torus.rotation.z = Math.PI * 0.87
    torus.castShadow = true
    g.add(torus)
    for (const s of [-1, 1]) {
      const tip = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.11, 0.24, 8), this.materials.gold)
      tip.position.set(s * 0.29, 0.34, 0)
      g.add(tip)
    }
    const glow = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: this.glowTex,
        color: 0xb07bff,
        transparent: true,
        opacity: 0.8,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      }),
    )
    glow.scale.set(2.2, 2.2, 1)
    g.add(glow)
    return g
  }

  createShieldMesh() {
    const g = new THREE.Group()
    const core = new THREE.Mesh(new THREE.IcosahedronGeometry(0.3, 0), this.shieldMat)
    core.castShadow = true
    g.add(core)
    const shell = new THREE.Mesh(
      new THREE.SphereGeometry(0.46, 12, 10),
      new THREE.MeshBasicMaterial({ color: 0x8ffbff, transparent: true, opacity: 0.22, wireframe: true }),
    )
    g.add(shell)
    const glow = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: this.glowTex,
        color: 0x6ff2ff,
        transparent: true,
        opacity: 0.8,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      }),
    )
    glow.scale.set(2.4, 2.4, 1)
    g.add(glow)
    return g
  }

  acquire(kind) {
    let mesh = this.pool[kind].pop()
    if (!mesh) {
      mesh =
        kind === 'coin'
          ? this.createCoinMesh()
          : kind === 'hurdle'
            ? this.createHurdleMesh()
            : kind === 'beam'
              ? this.createBeamMesh()
              : kind === 'blocker'
                ? this.createBlockerMesh()
                : kind === 'magnet'
                  ? this.createMagnetMesh()
                  : this.createShieldMesh()
      this.dynamicGroup.add(mesh)
    }
    mesh.visible = true
    mesh.scale.setScalar(1)
    return mesh
  }

  spawnCoin(x, y, z, kind = 'coin') {
    const mesh = this.acquire(kind)
    mesh.position.set(x, y, z)
    mesh.rotation.set(0, rand(0, Math.PI), 0)
    this.active.push({
      kind,
      mesh,
      x,
      y,
      z,
      baseY: y,
      spin: rand(0.8, 1.6),
      phase: rand(0, Math.PI * 2),
      collected: false,
      isCoin: kind === 'coin',
    })
  }

  spawnObstacle(kind, lane, z) {
    const mesh = this.acquire(kind)
    mesh.position.set(LANE_X[lane], 0, z)
    this.active.push({
      kind,
      mesh,
      x: LANE_X[lane],
      y: 0,
      z,
      lane,
      hit: false,
      collider: mesh.userData.collider,
    })
  }

  spawnPowerup(kind, lane, z) {
    const mesh = this.acquire(kind)
    mesh.position.set(LANE_X[lane], 1.25, z)
    this.active.push({
      kind,
      mesh,
      x: LANE_X[lane],
      y: 1.25,
      z,
      spin: 1.9,
      phase: rand(0, Math.PI * 2),
      collected: false,
      isPowerup: true,
    })
  }

  spawnRow() {
    const z = this.lastSpawnZ
    const cfg = this.cfg
    const diff = cfg.difficulty
    const roll = Math.random()
    let type = 'coins'
    if (this.rowCounter >= 2) {
      if (roll < 0.34) type = 'hurdle'
      else if (roll < 0.6) type = 'beam'
      else if (roll < 0.87) type = 'blocker'
    }

    const lanes = [0, 1, 2]
    let blocked = []

    if (type === 'hurdle') {
      const count = Math.random() < 0.22 + diff * 0.45 ? 3 : Math.random() < 0.5 ? 2 : 1
      blocked = shuffle(lanes).slice(0, count)
      blocked.forEach((l) => this.spawnObstacle('hurdle', l, z))
      // coin arc over the left-most hurdle lane
      const l = blocked[0]
      const x = LANE_X[l]
      for (let i = 0; i < 5; i++) {
        const t = i / 4
        this.spawnCoin(x, 1.05 + Math.sin(t * Math.PI) * 1.15, z + 3.2 - t * 6.4)
      }
      // coins in another lane
      if (Math.random() < 0.5) {
        const free = lanes.filter((n) => !blocked.includes(n))
        if (free.length) {
          const fl = pick(free)
          for (let i = 0; i < 4; i++) this.spawnCoin(LANE_X[fl], 1.0, z + 5 - i * 1.8)
        }
      }
    } else if (type === 'beam') {
      const count = Math.random() < 0.16 + diff * 0.35 ? 3 : Math.random() < 0.5 ? 2 : 1
      blocked = shuffle(lanes).slice(0, count)
      blocked.forEach((l) => this.spawnObstacle('beam', l, z))
      const free = lanes.filter((n) => !blocked.includes(n))
      const l = free.length ? pick(free) : pick(blocked)
      for (let i = 0; i < 5; i++) {
        this.spawnCoin(LANE_X[l], 0.58, z + 5.2 - i * 1.5)
      }
    } else if (type === 'blocker') {
      const count = diff > 0.3 && Math.random() < 0.3 + diff * 0.4 ? 2 : 1
      blocked = shuffle(lanes).slice(0, count)
      blocked.forEach((l) => this.spawnObstacle('blocker', l, z))
      const free = lanes.filter((n) => !blocked.includes(n))
      const l = pick(free)
      for (let i = 0; i < 7; i++) {
        this.spawnCoin(LANE_X[l], 1.0, z + 6.4 - i * 1.7)
      }
      if (free.length > 1 && Math.random() < 0.4) {
        const l2 = free.find((n) => n !== l)
        for (let i = 0; i < 4; i++) this.spawnCoin(LANE_X[l2], 1.0, z + 4 - i * 1.6)
      }
    } else {
      let l = randInt(0, 2)
      for (let i = 0; i < 7; i++) {
        this.spawnCoin(LANE_X[l], 1.0, z + 6 - i * 1.65)
        if (Math.random() < 0.24) l = clamp(l + pick([-1, 1]), 0, 2)
      }
    }

    if (Math.random() < 0.095) {
      const free = type === 'coins' ? lanes : lanes.filter((n) => !blocked.includes(n))
      const lane = free.length ? pick(free) : 1
      const kind = Math.random() < 0.52 ? 'magnet' : 'shield'
      this.spawnPowerup(kind, lane, z - 3)
    }

    this.rowCounter++
  }

  // ── main update ────────────────────────────────────────────
  loop() {
    requestAnimationFrame(this.loop)
    const dt = Math.min(this.clock.getDelta(), 0.05)
    if (this.state === 'paused') {
      this.renderer.render(this.scene, this.camera)
      return
    }
    this.time += dt
    this.update(dt)
    this.renderer.render(this.scene, this.camera)
  }

  update(dt) {
    const state = this.state
    if (country(state)) return

    // speed
    if (state === 'running') {
      this.elapsed += dt
      const cfg = this.cfg
      this.targetSpeed = Math.min(cfg.maxSpeed, cfg.startSpeed + this.elapsed * cfg.ramp * 0.55)
      if (this.stumble > 0) {
        this.stumble -= dt
        this.speed = damp(this.speed, this.targetSpeed * 0.55, 6, dt)
      } else {
        this.speed = damp(this.speed, this.targetSpeed, 2.2, dt)
      }
      this.distance += this.speed * dt
    } else if (state === 'attract') {
      this.attractT += dt
      this.speed = 4.2
    } else if (state === 'ready') {
      this.readyT += dt
      this.runPhase += dt * 8
      if (this.readyT >= this.readyTime) {
        this.state = 'running'
        this.cb.onGo?.()
      }
    } else if (state === 'dying' || state === 'finished') {
      this.speed = damp(this.speed, 2, 2, dt)
      if (state === 'dying') {
        this.deathT += dt
        this.rig.rotation.x += dt * 5
        this.rig.rotation.z += dt * 2
        if (this.deathT > 1.25 && !this.finishedNotified) {
          this.finishedNotified = true
          this.cb.onFail?.(this.result())
        }
      } else {
        this.finishT += dt
        if (this.finishT > 0.7 && !this.finishedNotified) {
          this.finishedNotified = true
          this.cb.onFinish?.(this.result())
        }
      }
    }

    // environment motion
    if (state !== 'ready' || this.readyT > 0.1) {
      const move = this.speed * dt
      for (const g of this.chunks) {
        g.position.z += move
        if (g.position.z > START_Z + CHUNK_LEN * 1.4) g.position.z -= CHUNK_LEN * CHUNK_COUNT
      }
    }
    this.updateDust(dt)
    this.updateFlames()
    this.updatePlayer(dt)
    this.updateCamera(dt)

    if (state === 'running') {
      this.updateSpawning(dt)
      this.updateItems(dt)
      this.checkFinish()
      this.checkStageFail()
      this.emitHud(false)
    } else if (state === 'attract') {
      this.updateItems(dt)
    }

    // animation for pickups etc.
    this.animateDecor(dt)
  }

  updateDust(dt) {
    const pos = this.dust.geometry.attributes.position
    const move = this.speed * dt
    for (let i = 0; i < pos.count; i++) {
      let z = pos.getZ(i) + move * 0.85
      if (z > 12) z -= 132
      let x = pos.getX(i) + Math.sin(this.time * 0.5 + this.dustSeeds[i]) * dt * 0.35
      if (x > 22) x = -22
      if (x < -22) x = 22
      pos.setZ(i, z)
      pos.setX(i, x)
    }
    pos.needsUpdate = true
  }

  updateFlames() {
    for (const f of this.flames) {
      if (!f.parent || !f.parent.visible) continue
      const s = 1 + Math.sin(this.time * 12 + f.userData.phase) * 0.18
      f.scale.set(s, 1.4 + s * 0.15, s)
    }
  }

  animateDecor(dt) {
    // gate shimmer
    if (this.gate && this.gate.visible) {
      this.gatePortal.material.opacity = 0.35 + Math.sin(this.time * 3) * 0.12
      this.gate.rotation.z = Math.sin(this.time * 1.2) * 0.01
    }
    if (this.relic) this.relic.rotation.y += dt * 1.8
    if (this.shieldMesh.visible) {
      this.shieldMesh.rotation.y += dt * 0.8
      this.shieldMesh.material.opacity = 0.11 + Math.sin(this.time * 4) * 0.05
    }
    if (this.magnetRingGroup.visible) {
      this.magnetRingGroup.rotation.y += dt * 2.2
      this.magnetRingGroup.children.forEach((r, i) => {
        r.rotation.z = this.time * (0.8 + i * 0.2)
      })
    }
  }

  updatePlayer(dt) {
    const targetX = LANE_X[this.laneIndex]
    const prevX = this.playerX
    this.playerX = damp(this.playerX, targetX, 15, dt)
    this.lean = damp(this.lean, clamp((targetX - this.playerX) * 0.4, -0.32, 0.32), 10, dt)
    this.player.position.x = this.playerX

    if (this.state === 'running' && this.grounded) this.runPhase += dt * (7.5 + this.speed * 0.34)
    else if (this.state === 'running') this.runPhase += dt * 3
    else if (this.state === 'attract') this.runPhase += dt * 9.5

    if (this.invuln > 0) {
      this.invuln -= dt
      this.player.visible = Math.floor(this.time * 14) % 2 === 0 ? true : this.invuln > 1.15 || this.invuln < 1.0
    } else {
      this.player.visible = true
    }

    // jump physics
    if (this.state === 'running' || this.state === 'ready') {
      if (!this.grounded) {
        this.vy += GRAVITY * dt
        this.playerY += this.vy * dt
        if (this.playerY <= 0) {
          this.playerY = 0
          this.vy = 0
          this.grounded = true
          this.landPulse = 0.14
          this.cb.onLand?.()
        }
      }
      if (this.landPulse > 0) this.landPulse -= dt
    }

    if (this.state === 'dying') {
      this.playerY = Math.max(0, this.playerY)
    }

    // slide timer
    if (this.sliding > 0) {
      this.sliding -= dt
      if (this.sliding <= 0) {
        this.sliding = 0
      }
    }
    const targetSlide = this.sliding > 0 ? 1 : 0
    this.slideAmt = damp(this.slideAmt, targetSlide, 18, dt)

    const p = this.player
    p.position.y = this.playerY

    // body pose
    const s = this.slideAmt
    const run = this.runPhase
    const grounded = this.grounded && this.state === 'running'
    const jumping = !this.grounded && (this.state === 'running' || this.state === 'ready')
    const idle = this.state === 'attract'

    const bob = grounded || idle ? Math.abs(Math.sin(run)) * 0.055 : 0
    const breathe = idle ? Math.sin(this.time * 2) * 0.01 : 0

    const legSwing = grounded ? Math.sin(run) * 0.92 : jumping ? 0.5 : 0
    const armSwing = grounded ? Math.sin(run + Math.PI) * 0.72 : jumping ? -1.5 : 0.1

    this.legs.forEach((leg, i) => {
      const dir = i === 0 ? 1 : -1
      const target = lerp(legSwing * dir, -1.35, s)
      leg.rotation.x = damp(leg.rotation.x, target + (jumping ? -0.5 : 0), 18, dt)
      leg.rotation.z = damp(leg.rotation.z, s * 0.06 * dir, 14, dt)
    })

    this.arms.forEach((arm, i) => {
      const dir = i === 0 ? 1 : -1
      const target = lerp(armSwing * dir, 0.5, s)
      arm.rotation.x = damp(arm.rotation.x, target + (jumping ? -0.6 : 0), 16, dt)
      arm.rotation.z = damp(arm.rotation.z, (i === 0 ? -1 : 1) * 0.1 + s * 0.5, 12, dt)
    })

    this.rig.rotation.x = damp(this.rig.rotation.x, lerp(-0.13, 1.32, s), 12, dt)
    this.rig.rotation.z = damp(this.rig.rotation.z, this.lean + (this.stumble > 0 ? Math.sin(this.time * 24) * 0.18 : 0), 10, dt)
    this.rig.rotation.y = damp(this.rig.rotation.y, -this.lean * 0.8, 8, dt)
    this.rig.position.y = damp(this.rig.position.y, bob + breathe - s * 0.62, 20, dt)

    // head look
    if (this.head) this.head.rotation.y = damp(this.head.rotation.y, -this.lean * 0.4, 8, dt)

    // scarf wave
    this.scarfLinks.forEach((link, i) => {
      link.rotation.x = -0.12 - i * 0.06 + Math.sin(run * 0.9 + i * 0.7) * 0.16
      link.position.x = Math.sin(run * 0.8 + i * 0.6) * 0.04 * (i + 1)
    })

    // blob shadow
    this.blob.position.set(this.playerX, 0.03, 0)
    const hFactor = clamp(1 - this.playerY / 4, 0.2, 1)
    this.blob.material.opacity = 0.45 * hFactor
    this.blob.scale.setScalar(lerp(1, 0.7, 1 - hFactor))

    // pickups visual state
    this.shieldMesh.visible = this.shield
    if (this.shield) this.shieldMesh.rotation.x = this.time * 0.4
    this.magnetRingGroup.visible = this.magnetTime > 0

    // powerup timers
    if (this.state === 'running') {
      if (this.magnetTime > 0) {
        this.magnetTime = Math.max(0, this.magnetTime - dt)
      }
      if (this.invuln > 0) this.invuln = Math.max(0, this.invuln - dt)
    }

    // stumble recovery pose
    if (this.stumble > 0) {
      this.stumble -= dt * 0.5
    }
  }

  updateCamera(dt) {
    const p = this.player
    const state = this.state
    if (state === 'attract') {
      const t = this.attractT
      this.camX = Math.sin(t * 0.18) * 2.6
      const camY = 4.6 + Math.sin(t * 0.24) * 0.35
      this.camera.position.set(this.camX, camY, 10.4 + Math.sin(t * 0.15) * 0.6)
      this.camera.lookAt(Math.sin(t * 0.1) * 0.6, 2.1, -18)
      return
    }

    const shakeAmt = this.shake
    if (shakeAmt > 0.001) {
      this.shake *= Math.exp(-dt * 5.5)
    } else this.shake = 0
    const sx = (Math.random() - 0.5) * this.shake * 0.5
    const sy = (Math.random() - 0.5) * this.shake * 0.4

    if (state === 'dying') {
      this.camX = damp(this.camX, this.playerX * 0.4, 3, dt)
      this.camera.position.x = this.camX + sx
      this.camera.position.y = damp(this.camera.position.y, 5.6, 2, dt) + sy
      this.camera.position.z = damp(this.camera.position.z, 11.5, 2, dt)
      this.camera.lookAt(this.playerX, 0.9, 0)
      return
    }

    if (state === 'finished') {
      const t = this.finishT
      const orbit = t * 0.8
      this.camera.position.set(Math.sin(orbit) * 4.2, 3.1 + Math.sin(t * 1.4) * 0.1, 5.2)
      this.camera.lookAt(0, 1.4, 0)
      return
    }

    this.camX = damp(this.camX, this.playerX * 0.55, 7, dt)
    const targetY = 4.55 + this.playerY * 0.2
    this.camY = damp(this.camY, targetY, 6, dt)
    const speedT = clamp((this.speed - (this.cfg?.startSpeed || 15)) / 10, 0, 1)
    const targetZ = 9.3 + speedT * 0.7
    this.camera.position.set(this.camX + sx, this.camY + sy, damp(this.camera.position.z, targetZ, 4, dt))
    this.camera.lookAt(this.playerX * 0.38, 1.7 + this.playerY * 0.35, -17)
    const targetFov = 59 + speedT * 5 + (this.magnetTime > 0 ? 1.5 : 0)
    this.fov = damp(this.fov, targetFov, 3, dt)
    this.camera.fov = this.fov
    this.camera.updateProjectionMatrix()
    this.rig.rotation.z += this.shake * 0.001
  }

  updateSpawning(dt) {
    if (this.gateSpawned) return
    const cfg = this.cfg
    this.lastSpawnZ += this.speed * dt
    const gapBase = Math.max(9.5, this.speed * (0.86 - cfg.difficulty * 0.26))
    while (this.lastSpawnZ > -150) {
      this.spawnRow()
      const gap = gapBase + rand(-1.2, 2.8)
      this.lastSpawnZ -= gap
    }
    if (!this.gateSpawned && this.distance >= cfg.distance - 45) {
      this.spawnGate()
    }
  }

  updateItems(dt) {
    const move = this.speed * dt
    const mag = this.magnetTime > 0
    const px = this.playerX
    const py = this.playerY + (this.slideAmt > 0.5 ? 0.5 : 1.0)
    const magnetRange = this.state === 'running' ? 8 : 0

    for (let i = this.active.length - 1; i >= 0; i--) {
      const it = this.active[i]
      it.z += move
      it.mesh.position.z = it.z

      if (it.kind === 'coin') {
        it.mesh.rotation.y += dt * it.spin * 2
        it.mesh.position.y = it.baseY + Math.sin(this.time * 3 + it.phase) * 0.055
        if (mag && this.state === 'running' && !it.collected) {
          const dx = px - it.mesh.position.x
          const dy = py - it.mesh.position.y
          const dz = 0 - it.z
          const d2 = dx * dx + dy * dy + dz * dz
          if (d2 < magnetRange * magnetRange) {
            const pull = 1 - Math.exp(-dt * 7)
            it.mesh.position.x += dx * pull
            it.mesh.position.y += dy * pull
            it.z += dz * pull
            it.mesh.position.z = it.z
          }
        }
        if (!it.collected && Math.abs(it.z) < 1.1) {
          const dx = Math.abs(px - it.mesh.position.x)
          const dy = Math.abs(py - it.mesh.position.y)
          if (dx < 0.95 && dy < 1.15) {
            this.collectCoin(it)
            it.collected = true
          }
        }
      } else if (it.isPowerup) {
        it.mesh.rotation.y += dt * it.spin
        it.mesh.position.y = it.y + Math.sin(this.time * 2.4 + it.phase) * 0.16
        if (!it.collected && this.state === 'running' && Math.abs(it.z) < 1.25) {
          const dx = Math.abs(px - it.mesh.position.x)
          const dy = Math.abs(py - it.mesh.position.y)
          if (dx < 1.15 && dy < 1.35) {
            this.collectPowerup(it)
            it.collected = true
          }
        }
      } else {
        // obstacle collision
        if (!it.hit && this.state === 'running' && Math.abs(it.z) < 1.05 && this.invuln <= 0 && !it.collected) {
          const c = it.collider
          const xOverlap = Math.abs(px - it.x) < c.hx + 0.32
          if (xOverlap && it.z > -0.85 && it.z < 0.9) {
            const playerTop = py - (this.slideAmt > 0.5 ? 0.5 : 1.0) + (this.slideAmt > 0.5 ? SLIDE_H : PLAYER_H)
            const feet = this.playerY
            let yOverlap = false
            if (it.kind === 'hurdle') {
              yOverlap = feet < c.y1 - 0.06
            } else if (it.kind === 'beam') {
              yOverlap = playerTop > c.y0 + 0.02
            } else {
              yOverlap = true
            }
            if (yOverlap) this.takeHit(it)
          }
        }
      }

      if (it.collected) {
        it.mesh.visible = false
        this.pool[it.kind]?.push(it.mesh)
        this.active.splice(i, 1)
        continue
      }
      if (it.z > 16) {
        it.mesh.visible = false
        this.pool[it.kind]?.push(it.mesh)
        this.active.splice(i, 1)
      }
    }

    // update finish gate
    if (this.gate && this.gate.visible) {
      this.finishGateZ += move
      this.gate.position.z = this.finishGateZ
      if (this.finishGateZ > 0.8 && this.state === 'running') {
        this.finish()
      }
    }
  }

  collectCoin(it) {
    this.coinCount++
    this.coinScore += this.coinValue
    this.cb.onCoin?.({ count: this.coinCount, value: this.coinScore })
  }

  collectPowerup(it) {
    if (it.kind === 'magnet') {
      this.magnetTime = this.magnetMax
      this.cb.onPowerup?.('magnet')
    } else {
      this.shield = true
      this.cb.onPowerup?.('shield')
    }
    this.cb.onPickupSound?.(it.kind)
  }

  takeHit(it) {
    it.hit = true
    if (this.shield) {
      this.shield = false
      this.invuln = 1.15
      this.shake = 0.55
      this.cb.onShieldBreak?.()
      this.cb.onHit?.({ shield: true })
      return
    }
    this.hearts -= 1
    this.hits += 1
    this.shake = 1
    this.stumble = 1.1
    this.invuln = 1.45
    this.magnetTime = 0
    this.cb.onHit?.({ shield: false, hearts: this.hearts })
    if (this.hearts <= 0) {
      this.state = 'dying'
      this.deathT = 0
      this.finishedNotified = false
      this.playerY = Math.max(this.playerY, 0)
      this.vy = Math.max(this.vy, 8)
      this.grounded = false
    }
  }

  checkStageFail() {
    if (this.state === 'running' && this.hearts <= 0) {
      // safety net; takeHit normally handles this
      this.state = 'dying'
      this.deathT = 0
    }
  }

  checkFinish() {
    if (this.finishGateZ !== null && this.finishGateZ > 0.8 && this.state === 'running') {
      this.finish()
    }
  }

  finish() {
    if (this.state !== 'running') return
    this.state = 'finished'
    this.finishT = 0
    this.finishedNotified = false
    this.cb.onFinishSound?.()
    this.cb.onFinishCue?.()
  }

  result() {
    const stars = this.computeStars()
    this.score = Math.floor(this.distance) * 10 + Math.floor(this.coinScore) * 25 + stars * 250
    return {
      cleared: this.state === 'finished',
      distance: Math.floor(this.distance),
      target: this.cfg.distance,
      coins: Math.floor(this.coinScore),
      coinCount: this.coinCount,
      coinGoal: this.cfg.coinGoal,
      hearts: Math.max(0, this.hearts),
      maxHearts: this.maxHearts,
      hits: this.hits,
      stars,
      score: this.score,
      time: this.elapsed,
      config: this.cfg,
      magnetTime: this.magnetTime,
    }
  }

  computeStars() {
    if (this.state !== 'finished') return 0
    let stars = 1
    if (Math.floor(this.coinScore) >= this.cfg.coinGoal) stars++
    if (this.hits === 0) stars++
    return stars
  }

  emitHud(force) {
    const now = this.time
    if (!force && now - this.lastHud < 0.055) return
    this.lastHud = now
    this.cb.onHud?.({
      state: this.state,
      distance: Math.floor(this.distance || 0),
      target: this.cfg?.distance || 0,
      coins: Math.floor(this.coinScore || 0),
      coinCount: this.coinCount || 0,
      coinGoal: this.cfg?.coinGoal || 0,
      hearts: Math.max(0, this.hearts ?? 0),
      maxHearts: this.maxHearts || 2,
      hits: this.hits || 0,
      speed: this.speed || 0,
      magnet: this.magnetTime || 0,
      magnetMax: this.magnetMax || 0,
      shield: !!this.shield,
      time: this.elapsed || 0,
      score: this.score || 0,
      starHints: {
        cleared: this.state === 'finished',
        coins: (this.coinScore || 0) >= (this.cfg?.coinGoal || 0),
        clean: (this.hits || 0) === 0,
      },
    })
  }

  // ── finish gate ────────────────────────────────────────────
  spawnGate() {
    if (!this.gate) this.buildGate()
    this.gate.visible = true
    this.finishGateZ = -42
    this.gate.position.z = this.finishGateZ
    this.gateSpawned = true

    // clear obstacles that sit beyond the gate
    for (let i = this.active.length - 1; i >= 0; i--) {
      const it = this.active[i]
      const isObstacle = !it.isCoin && !it.isPowerup
      if (isObstacle && it.z < this.finishGateZ - 3) {
        it.mesh.visible = false
        this.pool[it.kind]?.push(it.mesh)
        this.active.splice(i, 1)
      }
    }
  }

  buildGate() {
    const g = new THREE.Group()
    const M = this.materials
    const pillarGeo = new THREE.BoxGeometry(0.9, 7.2, 0.9)
    for (const s of [-1, 1]) {
      const p = new THREE.Mesh(pillarGeo, M.stone)
      p.position.set(s * 4.5, 3.2, 0)
      p.castShadow = true
      g.add(p)
      const cap = new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.35, 1.2), M.gold)
      cap.position.set(s * 4.5, 6.9, 0)
      g.add(cap)
      const base = new THREE.Mesh(new THREE.BoxGeometry(1.4, 0.5, 1.4), M.stoneDark)
      base.position.set(s * 4.5, 0.15, 0)
      g.add(base)
    }
    const lintel = new THREE.Mesh(new THREE.BoxGeometry(10.4, 1.1, 1.1), M.stoneDark)
    lintel.position.y = 7.4
    lintel.castShadow = true
    g.add(lintel)
    const trim = new THREE.Mesh(new THREE.BoxGeometry(10.6, 0.2, 1.3), M.gold)
    trim.position.y = 8.05
    g.add(trim)
    const crest = new THREE.Mesh(new THREE.ConeGeometry(1.1, 1.2, 4), M.gold)
    crest.position.y = 8.7
    crest.rotation.y = Math.PI / 4
    g.add(crest)

    this.gatePortal = new THREE.Mesh(
      new THREE.PlaneGeometry(8.2, 6.6),
      new THREE.MeshBasicMaterial({
        color: 0xffd36b,
        transparent: true,
        opacity: 0.35,
        blending: THREE.AdditiveBlending,
        side: THREE.DoubleSide,
        depthWrite: false,
      }),
    )
    this.gatePortal.position.y = 3.6
    g.add(this.gatePortal)

    // floating rune ring
    this.gateRing = new THREE.Mesh(
      new THREE.TorusGeometry(2.4, 0.06, 6, 48),
      new THREE.MeshBasicMaterial({
        color: 0xffe8a8,
        transparent: true,
        opacity: 0.8,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
      }),
    )
    this.gateRing.position.y = 3.6
    g.add(this.gateRing)

    const glow = new THREE.Sprite(M.glow.clone())
    glow.position.set(0, 4, 0)
    glow.scale.set(18, 18, 1)
    g.add(glow)

    g.visible = false
    this.gate = g
    this.dynamicGroup.add(g)
  }

  rebuildFinishGate() {
    if (this.gate) {
      this.dynamicGroup.remove(this.gate)
      this.gate = null
    }
  }

  // ── misc ───────────────────────────────────────────────────
  moveLane(dir) {
    if (this.state !== 'running' && this.state !== 'ready') return
    const next = clamp(this.laneIndex + dir, 0, 2)
    if (next === this.laneIndex) {
      this.cb.onEdge?.()
      return
    }
    this.laneIndex = next
    this.cb.onLane?.()
  }

  jump() {
    if (this.state !== 'running' && this.state !== 'ready') return
    if (this.sliding > 0) {
      this.sliding = 0
    }
    if (this.grounded) {
      this.vy = JUMP_V
      this.grounded = false
      this.playerY = 0.01
      this.cb.onJump?.()
    }
  }

  slide() {
    if (this.state !== 'running' && this.state !== 'ready') return
    if (this.grounded) {
      this.sliding = 0.62
      this.cb.onSlide?.()
    } else {
      this.vy = Math.min(this.vy, -24)
      this.cb.onSlide?.()
    }
  }

  resize() {
    const w = window.innerWidth
    const h = window.innerHeight
    this.renderer.setSize(w, h, false)
    this.camera.aspect = w / Math.max(1, h)
    this.camera.updateProjectionMatrix()
  }

  dispose() {
    this.resizeObserver?.disconnect()
    window.removeEventListener('keydown', this.onKey)
    this.renderer.dispose()
  }
}

function country(state) {
  return state === 'paused'
}

