/* ══════════════════════════════════════════════════════════════
   TEMPLE RUN 3D — interface
   ══════════════════════════════════════════════════════════════ */

:root {
  --bg: #0b0907;
  --ink: #f8f0dd;
  --ink-soft: #cdbda2;
  --ink-dim: #93826a;
  --gold: #f6c453;
  --gold-hi: #ffe9a9;
  --gold-deep: #b97a1e;
  --jade: #4ad9a4;
  --red: #e45a45;
  --violet: #b07bff;
  --cyan: #65e6ff;
  --line: rgba(246, 196, 83, 0.16);
  --line-soft: rgba(255, 240, 210, 0.09);
  --panel: rgba(20, 17, 13, 0.72);
  --panel-solid: rgba(18, 15, 12, 0.94);
  --shadow: 0 40px 90px -24px rgba(0, 0, 0, 0.9);
  --display: 'Cinzel', 'Times New Roman', serif;
  --ui: 'Manrope', 'Segoe UI', system-ui, sans-serif;
  --w1: #1d4e74;
  --w2: #ffc46b;
  --wa: #ffc94d;
  --wb: #ff7a3c;
}

* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
  margin: 0;
}

body {
  background: var(--bg);
  color: var(--ink);
  font-family: var(--ui);
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  padding: 0;
  cursor: pointer;
}

svg.sprite {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
}

.ico {
  width: 20px;
  height: 20px;
  flex: none;
  display: inline-block;
}

h1,
h2,
h3,
p {
  margin: 0;
}

kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  border-radius: 6px;
  border: 1px solid rgba(255, 235, 200, 0.2);
  background: rgba(255, 255, 255, 0.05);
  box-shadow: 0 2px 0 rgba(0, 0, 0, 0.45);
  font-family: var(--ui);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--ink-soft);
}

::selection {
  background: rgba(246, 196, 83, 0.3);
}

/* scrollbars */
*::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}
*::-webkit-scrollbar-thumb {
  background: rgba(246, 196, 83, 0.22);
  border-radius: 10px;
  border: 2px solid transparent;
  background-clip: padding-box;
}
*::-webkit-scrollbar-track {
  background: transparent;
}

/* ══ scene layers ═════════════════════════════════════════════ */
#app {
  position: fixed;
  inset: 0;
  isolation: isolate;
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  z-index: 0;
  background: #17120d;
}

.scene-shade {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(6, 5, 3, 0.95) 0%, rgba(6, 5, 3, 0.78) 30%, rgba(6, 5, 3, 0.24) 58%, rgba(6, 5, 3, 0.42) 100%),
    linear-gradient(180deg, rgba(6, 5, 3, 0.6) 0%, rgba(6, 5, 3, 0) 26%, rgba(6, 5, 3, 0) 66%, rgba(6, 5, 3, 0.82) 100%);
  transition: background 0.7s ease, backdrop-filter 0.7s ease;
}

#app[data-view='worlds'] .scene-shade,
#app[data-view='shop'] .scene-shade,
#app[data-view='help'] .scene-shade {
  background:
    radial-gradient(ellipse at 50% -10%, rgba(90, 60, 20, 0.22), transparent 55%),
    linear-gradient(180deg, rgba(7, 5, 4, 0.92), rgba(7, 5, 4, 0.8) 40%, rgba(7, 5, 4, 0.95));
  backdrop-filter: blur(2px);
}

#app[data-view='game'] .scene-shade {
  background:
    radial-gradient(ellipse at 50% 45%, transparent 42%, rgba(5, 4, 3, 0.42) 100%),
    linear-gradient(180deg, rgba(5, 4, 3, 0.55) 0%, transparent 18%, transparent 78%, rgba(5, 4, 3, 0.62) 100%);
}

.vignette {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background: radial-gradient(ellipse at 50% 46%, transparent 48%, rgba(0, 0, 0, 0.5) 100%);
}

.grain {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  opacity: 0.3;
  mix-blend-mode: overlay;
  background-image: radial-gradient(rgba(255, 255, 255, 0.16) 0.5px, transparent 0.6px);
  background-size: 3px 3px;
}

.embers {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  overflow: hidden;
}

.embers i {
  position: absolute;
  bottom: -10px;
  left: var(--x);
  width: var(--s);
  height: var(--s);
  border-radius: 50%;
  background: var(--wa);
  box-shadow: 0 0 12px 2px var(--wa);
  opacity: 0;
  animation: rise var(--d) linear var(--delay) infinite;
}

@keyframes rise {
  0% {
    transform: translate3d(0, 0, 0) scale(0.6);
    opacity: 0;
  }
  12% {
    opacity: 0.55;
  }
  80% {
    opacity: 0.25;
  }
  100% {
    transform: translate3d(var(--drift), -105vh, 0) scale(1.1);
    opacity: 0;
  }
}

/* ══ boot ════════════════════════════════════════════════════ */
.boot {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  background:
    radial-gradient(ellipse at 50% 45%, rgba(80, 54, 20, 0.4), transparent 62%),
    #080604;
  transition: opacity 0.7s ease, visibility 0.7s;
}

.boot.is-done {
  opacity: 0;
  visibility: hidden;
}

.boot-mark {
  position: relative;
  width: 116px;
  height: 116px;
  display: grid;
  place-items: center;
  margin-bottom: 6px;
}

.boot-mark .ico {
  width: 44px;
  height: 44px;
  color: var(--gold);
  filter: drop-shadow(0 0 18px rgba(246, 196, 83, 0.65));
}

.boot-ring {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 1px solid rgba(246, 196, 83, 0.18);
}

.boot-ring::before {
  content: '';
  position: absolute;
  inset: -1px;
  border-radius: 50%;
  border: 1.5px solid transparent;
  border-top-color: var(--gold);
  border-right-color: rgba(246, 196, 83, 0.35);
  animation: spin 1.5s linear infinite;
}

.boot-ring::after {
  content: '';
  position: absolute;
  inset: 18px;
  border-radius: 50%;
  border: 1px dashed rgba(246, 196, 83, 0.22);
  animation: spin 9s linear infinite reverse;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.boot-brand {
  font-family: var(--display);
  font-size: 20px;
  letter-spacing: 0.3em;
  color: var(--ink);
}

.boot-brand b {
  color: var(--gold);
  font-size: 12px;
  letter-spacing: 0.16em;
  vertical-align: middle;
  margin-left: 4px;
}

.boot-sub {
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-dim);
}

.boot-bar {
  width: 220px;
  height: 3px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
  margin-top: 8px;
}

.boot-bar i {
  display: block;
  height: 100%;
  width: 40%;
  border-radius: 4px;
  background: linear-gradient(90deg, transparent, var(--gold), transparent);
  animation: bootSlide 1.4s ease-in-out infinite;
}

@keyframes bootSlide {
  0% {
    transform: translateX(-110%);
  }
  100% {
    transform: translateX(320%);
  }
}

/* ══ top bar ═════════════════════════════════════════════════ */
.topbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px clamp(18px, 4vw, 52px);
  pointer-events: none;
  transition: opacity 0.3s;
}

#app[data-view='game'] .topbar {
  opacity: 0;
  visibility: hidden;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  pointer-events: auto;
  color: var(--ink);
}

.brand-mark {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: linear-gradient(150deg, #ffe9a9, #e8a72e 55%, #a2640f);
  color: #2a1a06;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7), 0 8px 20px -6px rgba(246, 180, 60, 0.6);
}

.brand-mark .ico {
  width: 21px;
  height: 21px;
}

.brand-text {
  font-family: var(--display);
  font-weight: 700;
  font-size: 15px;
  letter-spacing: 0.2em;
}

.brand-text b {
  color: var(--gold);
  font-size: 10px;
  letter-spacing: 0.1em;
  border: 1px solid rgba(246, 196, 83, 0.35);
  border-radius: 5px;
  padding: 2px 4px;
  vertical-align: 2px;
}

.top-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  pointer-events: auto;
}

.wallet {
  display: flex;
  align-items: center;
  gap: 7px;
  height: 40px;
  padding: 0 14px;
  border-radius: 12px;
  background: rgba(16, 13, 10, 0.62);
  border: 1px solid var(--line-soft);
  backdrop-filter: blur(14px);
  font-size: 13px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--ink);
}

.wallet .ico {
  width: 17px;
  height: 17px;
  color: var(--gold);
}

.wallet span {
  color: var(--ink-dim);
  font-size: 11px;
  font-weight: 500;
}

.wallet-star .ico {
  color: var(--gold);
}

.icon-btn {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: rgba(16, 13, 10, 0.62);
  border: 1px solid var(--line-soft);
  backdrop-filter: blur(14px);
  color: var(--ink-soft);
  transition: color 0.2s, border-color 0.2s, background 0.2s, transform 0.2s;
}

.icon-btn:hover {
  color: var(--gold);
  border-color: rgba(246, 196, 83, 0.4);
  background: rgba(246, 196, 83, 0.08);
}

.icon-btn:active {
  transform: scale(0.96);
}

.icon-btn .ico {
  width: 19px;
  height: 19px;
}

/* ══ shared screen chrome ════════════════════════════════════ */
.screen {
  position: fixed;
  inset: 0;
  z-index: 10;
  padding: 104px clamp(18px, 5.5vw, 88px) 44px;
  overflow-y: auto;
  overflow-x: hidden;
  opacity: 0;
  visibility: hidden;
  transform: translateY(16px);
  transition: opacity 0.42s ease, transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1), visibility 0.42s;
  overscroll-behavior: contain;
}

.screen.is-active {
  opacity: 1;
  visibility: visible;
  transform: none;
}

.screen-solid {
  background: radial-gradient(ellipse at 50% 0%, rgba(80, 56, 22, 0.16), transparent 55%);
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: var(--gold);
}

.eyebrow i {
  width: 26px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(246, 196, 83, 0.7));
}

.eyebrow i:last-child {
  background: linear-gradient(90deg, rgba(246, 196, 83, 0.7), transparent);
}

.screen-head {
  display: flex;
  align-items: center;
  gap: 18px;
  max-width: 1500px;
  margin: 0 auto 30px;
}

.back-btn {
  width: 46px;
  height: 46px;
  border-radius: 14px;
  flex: none;
}

.back-btn .ico {
  width: 20px;
  height: 20px;
}

.screen-title h2 {
  font-family: var(--display);
  font-size: clamp(26px, 3.2vw, 40px);
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1.1;
  margin-top: 5px;
}

.head-progress {
  margin-left: auto;
  width: min(300px, 32vw);
}

.head-progress-label {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-dim);
  margin-bottom: 7px;
}

.head-progress-label b {
  color: var(--gold);
  font-size: 11px;
}

.bare-bar {
  height: 5px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.bare-bar i {
  display: block;
  height: 100%;
  width: 0%;
  border-radius: 10px;
  background: linear-gradient(90deg, #d9962b, var(--gold), #ffecb0);
  box-shadow: 0 0 14px rgba(246, 196, 83, 0.5);
  transition: width 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.head-wallet {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 8px;
  height: 44px;
  padding: 0 18px;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: rgba(20, 16, 12, 0.7);
  font-variant-numeric: tabular-nums;
  font-size: 16px;
}

.head-wallet .ico {
  width: 20px;
  height: 20px;
  color: var(--gold);
}

.world-hint {
  max-width: 1500px;
  margin: 26px auto 0;
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-dim);
  text-align: center;
}

/* ══ buttons ═════════════════════════════════════════════════ */
.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  height: 52px;
  padding: 0 22px;
  border-radius: 15px;
  font-family: var(--ui);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.04em;
  white-space: nowrap;
  transition: transform 0.18s ease, box-shadow 0.25s ease, background 0.25s ease, border-color 0.25s ease;
  overflow: hidden;
  isolation: isolate;
}

.btn .ico {
  width: 18px;
  height: 18px;
}

.btn-gold {
  color: #2b1a06;
  background: linear-gradient(180deg, #ffe9a6 0%, #f6c453 46%, #dd9b2b 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.8),
    inset 0 -2px 0 rgba(120, 68, 6, 0.35),
    0 14px 30px -10px rgba(246, 181, 58, 0.6);
}

.btn-gold::after {
  content: '';
  position: absolute;
  inset: -2px;
  z-index: -1;
  background: linear-gradient(110deg, transparent 32%, rgba(255, 255, 255, 0.55) 47%, transparent 62%);
  transform: translateX(-130%);
  transition: transform 0.65s ease;
}

.btn-gold:hover {
  transform: translateY(-2px);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.8),
    inset 0 -2px 0 rgba(120, 68, 6, 0.35),
    0 20px 38px -10px rgba(246, 181, 58, 0.7);
}

.btn-gold:hover::after {
  transform: translateX(130%);
}

.btn-gold:active {
  transform: translateY(1px) scale(0.99);
}

.btn-ghost {
  color: var(--ink);
  background: rgba(255, 255, 255, 0.045);
  border: 1px solid rgba(255, 235, 200, 0.16);
  backdrop-filter: blur(10px);
}

.btn-ghost:hover {
  border-color: rgba(246, 196, 83, 0.45);
  background: rgba(246, 196, 83, 0.08);
  transform: translateY(-2px);
}

.btn-ghost:active {
  transform: translateY(0);
}

.btn-lg {
  height: 64px;
  padding: 0 26px;
  border-radius: 18px;
  font-size: 14px;
}

.btn-sm {
  height: 38px;
  padding: 0 16px;
  border-radius: 10px;
  font-size: 12px;
}

.btn-wide {
  width: 100%;
}

.btn-danger {
  color: #ffd9d1;
  border: 1px solid rgba(228, 90, 69, 0.4);
  background: rgba(228, 90, 69, 0.1);
}

.btn-danger:hover {
  background: rgba(228, 90, 69, 0.2);
}

.btn[disabled] {
  opacity: 0.42;
  pointer-events: none;
}

.btn-icon {
  width: 30px;
  height: 30px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  background: rgba(60, 34, 4, 0.16);
}

.btn-icon .ico {
  width: 15px;
  height: 15px;
}

.btn-stack {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  line-height: 1.2;
  gap: 2px;
}

.btn-stack small {
  font-size: 8.5px;
  letter-spacing: 0.24em;
  font-weight: 800;
  opacity: 0.6;
}

.btn-stack b {
  font-size: 13px;
  letter-spacing: 0.02em;
}

.link-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
  font-weight: 600;
  color: var(--ink-soft);
  padding: 6px 0;
  border-bottom: 1px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}

.link-btn .ico {
  width: 15px;
  height: 15px;
  color: var(--gold);
  opacity: 0.8;
}

.link-btn:hover {
  color: var(--gold-hi);
  border-color: rgba(246, 196, 83, 0.35);
}

/* ══ menu ════════════════════════════════════════════════════ */
.menu-screen {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  padding-top: 104px;
  padding-bottom: 26px;
}

.menu-grid {
  width: 100%;
  max-width: 1420px;
  margin: auto;
  display: grid;
  grid-template-columns: minmax(0, 1.14fr) minmax(320px, 0.86fr);
  align-items: center;
  gap: clamp(32px, 5vw, 76px);
}

.hero {
  max-width: 660px;
  animation: fadeUp 0.8s 0.05s both;
}

@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(18px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.hero > .eyebrow {
  margin-bottom: 18px;
}

.hero > .eyebrow i:first-child {
  display: none;
}

.logo {
  font-family: var(--display);
  line-height: 0.82;
  letter-spacing: 0.015em;
  font-weight: 800;
  text-transform: uppercase;
  user-select: none;
  filter: drop-shadow(0 18px 40px rgba(0, 0, 0, 0.55));
}

.logo-top {
  display: block;
  font-size: clamp(54px, 8.6vw, 126px);
  background: linear-gradient(180deg, #fffaf0 10%, #e9d3a6 62%, #b79563 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.logo-bottom {
  display: flex;
  align-items: center;
  gap: clamp(10px, 1.4vw, 20px);
  font-size: clamp(72px, 11.6vw, 168px);
  background: linear-gradient(180deg, #fff0b9 4%, #f6c453 38%, #dd9b2b 68%, #a2640f 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  margin-top: 2px;
}

.logo-bottom em {
  font-family: var(--ui);
  font-style: normal;
  font-size: clamp(11px, 1.1vw, 15px);
  font-weight: 800;
  letter-spacing: 0.2em;
  color: var(--gold-hi);
  background: rgba(35, 24, 9, 0.6);
  border: 1px solid rgba(246, 196, 83, 0.45);
  padding: 8px 9px 7px;
  border-radius: 8px;
  transform: translateY(4px) rotate(-4deg);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.35);
  text-shadow: none;
}

.tagline {
  font-size: clamp(14px, 1.4vw, 17px);
  line-height: 1.7;
  color: var(--ink-soft);
  margin-top: 22px;
  letter-spacing: 0.01em;
}

.hero-actions {
  display: flex;
  align-items: stretch;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 30px;
}

.hero-actions #btn-play {
  min-width: 232px;
  justify-content: flex-start;
  padding-left: 14px;
}

.hero-links {
  display: flex;
  align-items: center;
  gap: 26px;
  margin-top: 20px;
}

.stat-row {
  display: flex;
  gap: clamp(24px, 4vw, 54px);
  margin-top: 34px;
  padding-top: 22px;
  border-top: 1px solid rgba(255, 235, 200, 0.1);
  max-width: 520px;
}

.stat-row div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-row b {
  font-family: var(--display);
  font-size: 24px;
  font-weight: 700;
  color: var(--gold-hi);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.stat-row span {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-dim);
}

.menu-footer {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 22px;
  width: 100%;
  max-width: 1420px;
  margin: 44px auto 0;
  padding-top: 16px;
  border-top: 1px solid rgba(255, 235, 200, 0.07);
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-dim);
  animation: fadeUp 0.8s 0.35s both;
}

.menu-footer span {
  display: flex;
  align-items: center;
  gap: 6px;
}

.menu-footer .footer-note {
  margin-left: auto;
  text-transform: none;
  letter-spacing: 0.02em;
  font-size: 10.5px;
  opacity: 0.8;
}

/* continue card */
.continue-card {
  width: 100%;
  max-width: 452px;
  justify-self: end;
  border-radius: 26px;
  overflow: hidden;
  background: linear-gradient(180deg, rgba(31, 26, 20, 0.82), rgba(13, 11, 9, 0.94));
  border: 1px solid rgba(255, 235, 200, 0.14);
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(20px) saturate(120%);
  animation: fadeUp 0.85s 0.18s both;
  transition: border-color 0.3s, box-shadow 0.3s;
}

.continue-card:hover {
  border-color: rgba(246, 196, 83, 0.3);
  box-shadow: var(--shadow), 0 0 60px -20px rgba(246, 196, 83, 0.3);
}

.cc-art {
  position: relative;
  height: 188px;
  overflow: hidden;
  background: linear-gradient(140deg, var(--w1) 0%, var(--w2) 100%);
  color: #160f08;
  isolation: isolate;
}

.cc-art::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 80% 120%, rgba(255, 255, 255, 0.35), transparent 55%),
    linear-gradient(180deg, rgba(12, 9, 6, 0.28) 0%, transparent 38%, rgba(13, 11, 9, 0.92) 100%);
}

.cc-glow {
  position: absolute;
  width: 240px;
  height: 240px;
  right: -50px;
  top: -80px;
  border-radius: 50%;
  background: var(--wa);
  filter: blur(60px);
  opacity: 0.45;
}

.cc-temple {
  position: absolute;
  left: -4%;
  bottom: 10%;
  width: 108%;
  height: 100%;
  color: rgba(15, 10, 5, 0.42);
  filter: drop-shadow(0 20px 40px rgba(0, 0, 0, 0.3));
}

.cc-world-tag {
  position: absolute;
  z-index: 2;
  top: 16px;
  left: 18px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 26px;
  padding: 0 10px;
  border-radius: 8px;
  background: rgba(15, 11, 7, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.18);
  backdrop-filter: blur(8px);
  color: #fff6e2;
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: 0.22em;
}

.cc-world-tag b {
  color: var(--gold-hi);
  font-size: 10px;
}

.cc-ghost {
  position: absolute;
  right: 14px;
  top: 4px;
  z-index: 2;
  font-family: var(--display);
  font-size: 92px;
  line-height: 1;
  font-weight: 800;
  color: rgba(255, 252, 240, 0.3);
  mix-blend-mode: overlay;
  user-select: none;
}

.cc-stage-chip {
  position: absolute;
  z-index: 2;
  bottom: 16px;
  left: 18px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.24em;
  color: #fff6e2;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.6);
}

.cc-body {
  padding: 18px 22px 22px;
  position: relative;
}

.cc-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.cc-name {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 3px;
}

.cc-head h3 {
  font-family: var(--display);
  font-size: 26px;
  font-weight: 700;
  line-height: 1.08;
}

.cc-stars {
  display: flex;
  align-items: center;
  gap: 4px;
  padding-top: 4px;
  color: var(--gold);
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
}

.cc-stars .ico {
  width: 15px;
  height: 15px;
}

.cc-stars span {
  color: var(--ink-dim);
  font-size: 10px;
  font-weight: 600;
}

.cc-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 14px 0 16px;
}

.cc-meta span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 28px;
  padding: 0 9px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.06);
  font-size: 10px;
  font-weight: 600;
  color: var(--ink-dim);
}

.cc-meta .ico {
  width: 13px;
  height: 13px;
  color: var(--gold);
}

.cc-meta b {
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
}

.cc-body .btn-wide {
  height: 50px;
  border-radius: 13px;
  justify-content: space-between;
  padding: 0 16px 0 20px;
  font-size: 12.5px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.cc-tip {
  margin-top: 12px;
  font-size: 10.5px;
  line-height: 1.5;
  color: var(--ink-dim);
}

.cc-tip b {
  color: var(--ink-soft);
}

.cc-progress {
  margin-top: 16px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.cc-progress > span {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: var(--ink-dim);
}

.cc-progress > div {
  flex: 1;
  height: 4px;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.cc-progress i {
  display: block;
  height: 100%;
  width: 0;
  border-radius: 6px;
  background: linear-gradient(90deg, #d9962b, var(--gold));
  transition: width 0.6s ease;
}

/* ══ world grid ══════════════════════════════════════════════ */
.world-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(238px, 1fr));
  gap: clamp(12px, 1.4vw, 20px);
  max-width: 1500px;
  margin: 0 auto;
  perspective: 1400px;
}

.world-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 252px;
  padding: 0;
  border-radius: 20px;
  overflow: hidden;
  text-align: left;
  background: linear-gradient(180deg, rgba(30, 25, 19, 0.82), rgba(13, 11, 9, 0.95));
  border: 1px solid rgba(255, 235, 200, 0.1);
  box-shadow: 0 20px 40px -24px rgba(0, 0, 0, 0.9);
  transform-style: preserve-3d;
  transition: transform 0.24s ease, border-color 0.24s, box-shadow 0.24s, opacity 0.3s;
  will-change: transform;
  animation: cardIn 0.55s backwards;
}

@keyframes cardIn {
  from {
    opacity: 0;
    transform: translateY(22px) scale(0.97);
  }
}

.world-card:hover {
  border-color: rgba(246, 196, 83, 0.36);
  box-shadow: 0 30px 60px -26px rgba(0, 0, 0, 0.95), 0 0 0 1px rgba(246, 196, 83, 0.08);
  z-index: 2;
}

.world-card:active {
  transform: scale(0.99);
}

.wc-art {
  position: relative;
  height: 138px;
  flex: none;
  overflow: hidden;
  background: linear-gradient(150deg, var(--w1) 0%, var(--w2) 100%);
  color: #1b130a;
  isolation: isolate;
}

.wc-art::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 80% 130%, rgba(255, 255, 255, 0.32), transparent 58%),
    linear-gradient(180deg, rgba(10, 7, 4, 0.16) 0%, transparent 34%, rgba(13, 11, 9, 0.88) 100%);
}

.wc-temple {
  position: absolute;
  left: -6%;
  bottom: 0;
  width: 112%;
  height: 92%;
  color: rgba(20, 13, 6, 0.38);
  transition: transform 0.5s ease;
}

.world-card:hover .wc-temple {
  transform: scale(1.04) translateY(-2px);
}

.wc-num {
  position: absolute;
  z-index: 2;
  top: 8px;
  right: 12px;
  font-family: var(--display);
  font-size: 52px;
  font-weight: 800;
  line-height: 1;
  color: rgba(255, 250, 235, 0.28);
  mix-blend-mode: overlay;
  pointer-events: none;
}

.wc-tag {
  position: absolute;
  z-index: 2;
  top: 12px;
  left: 12px;
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.22em;
  color: rgba(20, 13, 6, 0.65);
  background: rgba(255, 250, 235, 0.32);
  border-radius: 5px;
  padding: 4px 6px;
  backdrop-filter: blur(4px);
}

.wc-lock,
.wc-crown {
  position: absolute;
  z-index: 4;
  left: 50%;
  top: 48%;
  transform: translate(-50%, -50%);
  width: 46px;
  height: 46px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(10, 8, 6, 0.62);
  border: 1px solid rgba(255, 235, 200, 0.22);
  color: var(--ink-soft);
  backdrop-filter: blur(8px);
  opacity: 0;
  transition: opacity 0.25s;
}

.wc-lock .ico,
.wc-crown .ico {
  width: 20px;
  height: 20px;
}

.is-locked .wc-lock {
  opacity: 1;
}

.is-locked .wc-art {
  filter: grayscale(0.65) brightness(0.52);
}

.is-locked .wc-temple {
  opacity: 0.5;
}

.is-locked {
  cursor: not-allowed;
}

.is-locked .wc-body {
  opacity: 0.5;
}

.is-mastered .wc-crown {
  opacity: 1;
  color: var(--gold);
  border-color: rgba(246, 196, 83, 0.5);
}

.is-frontier {
  border-color: rgba(246, 196, 83, 0.45);
  animation: cardIn 0.55s backwards, frontierPulse 2.8s ease-in-out infinite;
}

@keyframes frontierPulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(246, 196, 83, 0);
  }
  50% {
    box-shadow: 0 0 0 3px rgba(246, 196, 83, 0.16), 0 20px 50px -25px rgba(246, 196, 83, 0.4);
  }
}

.wc-body {
  padding: 12px 14px 14px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  flex: 1;
}

.wc-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.wc-top h3 {
  font-family: var(--display);
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.01em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.wc-starcount {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 10px;
  font-weight: 700;
  color: var(--ink-dim);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.wc-starcount .ico {
  width: 11px;
  height: 11px;
  color: var(--gold);
  opacity: 0.9;
}

.wc-blurb {
  font-size: 10.5px;
  line-height: 1.45;
  color: var(--ink-dim);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  min-height: 30px;
}

.wc-pips {
  display: flex;
  gap: 4px;
  margin-top: auto;
  padding-top: 8px;
}

.wc-pips i {
  flex: 1;
  height: 4px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.1);
  overflow: hidden;
  position: relative;
}

.wc-pips i::after {
  content: '';
  position: absolute;
  inset: 0;
  width: var(--fill, 0%);
  border-radius: 4px;
  background: linear-gradient(90deg, #d9962b, var(--gold));
}

/* ══ shop ════════════════════════════════════════════════════ */
.shop-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(290px, 1fr));
  gap: 18px;
  max-width: 1180px;
  margin: 0 auto;
}

.shop-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 24px;
  border-radius: 22px;
  background: linear-gradient(165deg, rgba(34, 28, 21, 0.8), rgba(13, 11, 9, 0.94));
  border: 1px solid rgba(255, 235, 200, 0.12);
  box-shadow: 0 30px 60px -30px rgba(0, 0, 0, 0.9), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  overflow: hidden;
}

.shop-card::before {
  content: '';
  position: absolute;
  inset: -60% 40% auto -20%;
  height: 220px;
  background: radial-gradient(ellipse, rgba(246, 196, 83, 0.12), transparent 60%);
  pointer-events: none;
}

.shop-icon {
  width: 54px;
  height: 54px;
  border-radius: 16px;
  display: grid;
  place-items: center;
  margin-bottom: 16px;
  background: linear-gradient(150deg, rgba(246, 196, 83, 0.18), rgba(246, 196, 83, 0.04));
  border: 1px solid rgba(246, 196, 83, 0.22);
  color: var(--gold);
}

.shop-icon .ico {
  width: 26px;
  height: 26px;
}

.shop-card[data-type='heart'] .shop-icon {
  color: var(--red);
  background: linear-gradient(150deg, rgba(228, 90, 69, 0.18), rgba(228, 90, 69, 0.03));
  border-color: rgba(228, 90, 69, 0.24);
}

.shop-card[data-type='value'] .shop-icon {
  color: var(--jade);
  background: linear-gradient(150deg, rgba(74, 217, 164, 0.16), rgba(74, 217, 164, 0.03));
  border-color: rgba(74, 217, 164, 0.24);
}

.shop-card h3 {
  font-family: var(--display);
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 6px;
}

.shop-desc {
  font-size: 12px;
  line-height: 1.6;
  color: var(--ink-dim);
  min-height: 58px;
}

.shop-rank {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 16px 0 12px;
}

.shop-rank span {
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: var(--ink-dim);
}

.rank-pips {
  display: flex;
  gap: 4px;
  flex: 1;
}

.rank-pips i {
  height: 5px;
  flex: 1;
  max-width: 34px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.1);
}

.rank-pips i.on {
  background: linear-gradient(90deg, #d9962b, var(--gold));
  box-shadow: 0 0 8px rgba(246, 196, 83, 0.35);
}

.shop-effect {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  align-self: flex-start;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--gold);
  background: rgba(246, 196, 83, 0.08);
  border: 1px solid rgba(246, 196, 83, 0.16);
  border-radius: 8px;
  padding: 6px 9px;
  margin-bottom: 18px;
}

.shop-buy {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  width: 100%;
  height: 48px;
  padding: 0 14px 0 18px;
  margin-top: auto;
  border-radius: 12px;
  background: linear-gradient(180deg, #ffe9a6, #f6c453 46%, #dd9b2b);
  color: #2b1a06;
  font-weight: 800;
  font-size: 12px;
  letter-spacing: 0.06em;
  transition: transform 0.2s, filter 0.2s, opacity 0.2s;
}

.shop-buy span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.shop-buy .ico {
  width: 16px;
  height: 16px;
}

.shop-buy:hover {
  filter: brightness(1.06);
  transform: translateY(-1px);
}

.shop-buy[disabled] {
  background: rgba(255, 255, 255, 0.06);
  color: var(--ink-dim);
  border: 1px solid rgba(255, 255, 255, 0.08);
  cursor: not-allowed;
  transform: none;
  filter: none;
}

.shop-buy .cost {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 13px;
  background: rgba(70, 40, 4, 0.18);
  border-radius: 8px;
  padding: 5px 9px;
}

.shop-buy[disabled] .cost {
  background: rgba(255, 255, 255, 0.05);
}

/* ══ help ════════════════════════════════════════════════════ */
.help-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 14px;
  max-width: 1220px;
  margin: 0 auto;
}

.help-card {
  padding: 22px;
  border-radius: 18px;
  background: rgba(24, 20, 15, 0.72);
  border: 1px solid rgba(255, 235, 200, 0.1);
  backdrop-filter: blur(12px);
}

.help-icon {
  display: flex;
  gap: 6px;
  color: var(--gold);
  margin-bottom: 12px;
}

.help-icon .ico {
  width: 24px;
  height: 24px;
}

.help-icon.gold {
  color: var(--gold);
}
.help-icon.purple {
  color: var(--violet);
}
.help-icon.cyan {
  color: var(--cyan);
}

.help-card h3 {
  font-family: var(--display);
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 7px;
}

.help-card p {
  font-size: 11.5px;
  line-height: 1.65;
  color: var(--ink-dim);
}

.help-card p b {
  color: var(--ink-soft);
}

.key-row {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 13px;
  flex-wrap: wrap;
}

.key-row span {
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--ink-dim);
  margin-left: 3px;
}

.star-key {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 13px;
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--ink-dim);
}

.star-key span {
  color: var(--gold);
  letter-spacing: 0.05em;
}

.help-foot {
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: 1220px;
  margin: 20px auto 0;
  padding: 16px 20px;
  border-radius: 14px;
  border: 1px dashed rgba(246, 196, 83, 0.2);
  background: rgba(246, 196, 83, 0.04);
  color: var(--gold);
}

.help-foot .ico {
  width: 22px;
  height: 22px;
  flex: none;
}

.help-foot p {
  font-size: 11.5px;
  line-height: 1.5;
  color: var(--ink-dim);
}

/* ══ HUD ═════════════════════════════════════════════════════ */
.hud {
  position: fixed;
  inset: 0;
  z-index: 20;
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.35s ease, visibility 0.35s;
}

.hud.is-active {
  opacity: 1;
  visibility: visible;
}

.hud-top {
  display: grid;
  grid-template-columns: 1fr minmax(300px, 540px) 1fr;
  align-items: start;
  gap: clamp(10px, 2vw, 26px);
  padding: max(18px, env(safe-area-inset-top)) clamp(14px, 2.6vw, 34px) 0;
}

.hud-left {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 10px;
  padding-top: 4px;
}

.hearts {
  display: flex;
  gap: 6px;
  filter: drop-shadow(0 4px 10px rgba(0, 0, 0, 0.5));
}

.heart {
  width: 26px;
  height: 26px;
  color: var(--red);
  position: relative;
  transition: color 0.25s, transform 0.25s, opacity 0.25s;
}

.heart svg {
  width: 100%;
  height: 100%;
  filter: drop-shadow(0 0 8px rgba(228, 90, 69, 0.45));
}

.heart.is-empty {
  color: rgba(255, 255, 255, 0.18);
}

.heart.is-empty svg {
  filter: none;
}

.heart.is-lost {
  animation: heartLost 0.5s ease both;
}

@keyframes heartLost {
  0% {
    transform: scale(1);
  }
  35% {
    transform: scale(1.5) rotate(-8deg);
    color: #fff;
  }
  100% {
    transform: scale(1);
  }
}

.pu-wrap {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.pu {
  display: none;
  align-items: center;
  gap: 8px;
  height: 36px;
  padding: 0 10px 0 8px;
  border-radius: 10px;
  background: rgba(16, 13, 10, 0.7);
  border: 1px solid rgba(176, 123, 255, 0.3);
  backdrop-filter: blur(10px);
  box-shadow: 0 8px 20px -10px rgba(0, 0, 0, 0.8);
}

.pu.is-on {
  display: flex;
  animation: puIn 0.3s ease both;
}

@keyframes puIn {
  from {
    opacity: 0;
    transform: translateX(-10px);
  }
}

.pu-icon {
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  color: var(--violet);
}

.pu-icon .ico {
  width: 17px;
  height: 17px;
}

.pu-text {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 78px;
}

.pu-text b {
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: var(--ink-soft);
}

.pu-bar {
  display: block;
  width: 100%;
  height: 3px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.12);
  overflow: hidden;
}

.pu-bar i {
  display: block;
  height: 100%;
  width: 100%;
  border-radius: 4px;
  background: linear-gradient(90deg, #8a4dff, var(--violet));
  transition: width 0.15s linear;
}

.pu em {
  font-style: normal;
  font-size: 10px;
  font-weight: 700;
  color: var(--violet);
  font-variant-numeric: tabular-nums;
}

.pu-shield {
  border-color: rgba(101, 230, 255, 0.35);
}

.pu-shield .pu-icon,
.pu-shield em {
  color: var(--cyan);
}

.pu-shield .pu-bar i {
  background: linear-gradient(90deg, #1b9cb5, var(--cyan));
}

.hud-center {
  padding: 11px 16px 10px;
  border-radius: 16px;
  background: linear-gradient(180deg, rgba(20, 16, 12, 0.82), rgba(14, 11, 9, 0.62));
  border: 1px solid rgba(255, 235, 200, 0.13);
  backdrop-filter: blur(16px) saturate(130%);
  box-shadow: 0 16px 40px -20px rgba(0, 0, 0, 0.9), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  text-align: center;
}

.run-title {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-dim);
  margin-bottom: 8px;
  white-space: nowrap;
}

.run-title .run-world {
  color: var(--ink-soft);
  font-weight: 700;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 42%;
}

.run-title i {
  opacity: 0.4;
  font-style: normal;
}

.run-title b {
  color: var(--gold);
  font-weight: 800;
  font-size: 9px;
}

.run-progress {
  position: relative;
}

.progress-track {
  position: relative;
  height: 7px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.1);
  overflow: visible;
}

.progress-track > i {
  display: block;
  height: 100%;
  width: 0;
  border-radius: 8px;
  background: linear-gradient(90deg, #c1811c, var(--gold) 70%, #ffedb4);
  box-shadow: 0 0 14px rgba(246, 196, 83, 0.55);
  transition: width 0.14s linear;
  position: relative;
}

.marker {
  position: absolute;
  top: 50%;
  left: 0;
  width: 10px;
  height: 10px;
  border-radius: 2px;
  background: #fff8e4;
  border: 1px solid rgba(120, 74, 8, 0.6);
  box-shadow: 0 0 12px rgba(255, 240, 180, 0.9);
  transform: translate(-50%, -50%) rotate(45deg);
  transition: left 0.14s linear;
}

.progress-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 7px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--ink-dim);
  font-variant-numeric: tabular-nums;
}

.progress-meta span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.progress-meta .ico {
  width: 12px;
  height: 12px;
  color: var(--gold);
}

.progress-meta b {
  color: var(--ink-soft);
}

#hud-goal.is-done {
  color: var(--gold);
}

#hud-goal.is-done b {
  color: var(--gold-hi);
}

.star-hints {
  display: flex;
  justify-content: center;
  gap: 5px;
  margin-top: 8px;
}

.hint {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  height: 18px;
  padding: 0 7px 0 5px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--ink-dim);
  opacity: 0.6;
  transition: all 0.3s;
}

.hint .ico {
  width: 10px;
  height: 10px;
  opacity: 0.6;
}

.hint.is-on {
  color: var(--gold);
  background: rgba(246, 196, 83, 0.1);
  border-color: rgba(246, 196, 83, 0.22);
  opacity: 1;
}

.hint.is-on .ico {
  opacity: 1;
}

.hud-right {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding-top: 2px;
}

.coin-pill {
  display: flex;
  align-items: center;
  gap: 7px;
  height: 40px;
  padding: 0 13px;
  border-radius: 12px;
  background: rgba(20, 16, 12, 0.72);
  border: 1px solid rgba(246, 196, 83, 0.22);
  backdrop-filter: blur(12px);
  box-shadow: 0 10px 24px -12px rgba(0, 0, 0, 0.8);
  font-size: 15px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.coin-pill .ico {
  width: 18px;
  height: 18px;
  color: var(--gold);
}

.coin-pill b {
  color: var(--gold-hi);
}

.pause-btn {
  width: 40px;
  height: 40px;
  pointer-events: auto;
}

.hud-bottom {
  position: absolute;
  bottom: max(18px, env(safe-area-inset-bottom));
  left: clamp(14px, 2.6vw, 34px);
  right: clamp(14px, 2.6vw, 34px);
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
}

.control-hint {
  display: flex;
  gap: 16px;
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: rgba(248, 240, 221, 0.52);
}

.control-hint span {
  display: flex;
  align-items: center;
  gap: 5px;
}

.speed-chip {
  display: flex;
  align-items: baseline;
  gap: 3px;
  height: 32px;
  padding: 0 11px;
  border-radius: 9px;
  background: rgba(16, 13, 10, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(8px);
  color: var(--ink-dim);
  font-size: 8px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.speed-chip b {
  font-family: var(--display);
  font-size: 18px;
  color: var(--gold);
  font-variant-numeric: tabular-nums;
}

.touch-controls {
  display: none;
  position: absolute;
  left: 50%;
  bottom: calc(max(16px, env(safe-area-inset-bottom)) + 6px);
  transform: translateX(-50%);
  gap: 10px;
  pointer-events: auto;
}

.touch-btn {
  width: 58px;
  height: 58px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(18, 15, 12, 0.6);
  border: 1px solid rgba(255, 235, 200, 0.2);
  backdrop-filter: blur(10px);
  color: var(--ink-soft);
  box-shadow: 0 10px 24px -10px rgba(0, 0, 0, 0.8);
  transition: background 0.15s, transform 0.1s;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

.touch-btn .ico {
  width: 24px;
  height: 24px;
}

.touch-btn:active {
  background: rgba(246, 196, 83, 0.18);
  border-color: rgba(246, 196, 83, 0.45);
  color: var(--gold);
  transform: scale(0.94);
}

.touch-btn[data-action='jump'] {
  width: 66px;
  height: 66px;
  color: var(--gold);
  border-color: rgba(246, 196, 83, 0.3);
}

.hud-toast {
  position: absolute;
  left: 50%;
  top: 30%;
  transform: translate(-50%, -50%) scale(0.92);
  padding: 10px 18px;
  border-radius: 12px;
  background: rgba(16, 13, 10, 0.82);
  border: 1px solid rgba(246, 196, 83, 0.3);
  backdrop-filter: blur(14px);
  color: var(--gold-hi);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  opacity: 0;
  transition: opacity 0.25s, transform 0.35s cubic-bezier(0.2, 0.9, 0.3, 1.3);
  white-space: nowrap;
  pointer-events: none;
  box-shadow: 0 20px 40px -16px rgba(0, 0, 0, 0.8);
}

.hud-toast.show {
  opacity: 1;
  transform: translate(-50%, -50%) scale(1);
}

.hud-toast.purple {
  border-color: rgba(176, 123, 255, 0.45);
  color: #e3ccff;
}
.hud-toast.cyan {
  border-color: rgba(101, 230, 255, 0.45);
  color: #c6f8ff;
}

.countdown {
  position: fixed;
  inset: 0;
  z-index: 34;
  display: grid;
  place-items: center;
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.2s, visibility 0.2s;
}

.countdown span {
  font-family: var(--display);
  font-size: clamp(56px, 10vw, 120px);
  font-weight: 800;
  letter-spacing: 0.12em;
  background: linear-gradient(180deg, #fff8e2, #f6c453 55%, #c1811c);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: 0 24px 60px rgba(0, 0, 0, 0.7);
  filter: drop-shadow(0 0 30px rgba(246, 196, 83, 0.35));
}

.countdown.show {
  opacity: 1;
  visibility: visible;
}

.countdown.show span {
  animation: countPop 0.7s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.countdown.is-go span {
  animation: goPop 0.8s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes countPop {
  0% {
    opacity: 0;
    transform: scale(1.5);
    filter: blur(8px);
  }
  100% {
    opacity: 1;
    transform: scale(1);
    filter: blur(0);
  }
}

@keyframes goPop {
  0% {
    opacity: 0;
    transform: scale(0.5);
  }
  25% {
    opacity: 1;
    transform: scale(1.15);
  }
  60% {
    opacity: 1;
    transform: scale(1);
  }
  100% {
    opacity: 0;
    transform: scale(1.3);
  }
}

.flash {
  position: fixed;
  inset: 0;
  z-index: 25;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(ellipse at 50% 60%, rgba(228, 90, 69, 0.08), rgba(228, 90, 69, 0.5));
}

.flash.hit {
  animation: flashHit 0.6s ease-out both;
}

.flash.gold {
  background: radial-gradient(ellipse at 50% 55%, rgba(246, 196, 83, 0.05), rgba(255, 227, 150, 0.35));
  animation: flashGold 0.8s ease-out both;
}

@keyframes flashHit {
  0% {
    opacity: 0;
  }
  12% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}

@keyframes flashGold {
  0% {
    opacity: 0;
  }
  15% {
    opacity: 0.9;
  }
  100% {
    opacity: 0;
  }
}

/* ══ overlays & modals ═══════════════════════════════════════ */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 18px;
  background: rgba(5, 4, 3, 0.58);
  backdrop-filter: blur(9px) saturate(110%);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease, visibility 0.3s;
  overflow-y: auto;
}

.overlay.is-open {
  opacity: 1;
  visibility: visible;
}

.modal,
.sheet {
  position: relative;
  width: min(560px, 100%);
  max-height: calc(100vh - 36px);
  overflow-y: auto;
  padding: 28px;
  border-radius: 26px;
  background:
    radial-gradient(ellipse at 20% -10%, rgba(246, 196, 83, 0.1), transparent 46%),
    linear-gradient(180deg, rgba(28, 23, 18, 0.96), rgba(13, 11, 9, 0.98));
  border: 1px solid rgba(255, 235, 200, 0.16);
  box-shadow: 0 50px 110px -30px rgba(0, 0, 0, 0.95), inset 0 1px 0 rgba(255, 255, 255, 0.07);
  transform: translateY(22px) scale(0.97);
  transition: transform 0.4s cubic-bezier(0.2, 0.85, 0.25, 1.1);
  scrollbar-gutter: stable;
}

.overlay.is-open .modal,
.overlay.is-open .sheet {
  transform: none;
}

.modal h2 {
  font-family: var(--display);
  font-size: clamp(24px, 3.4vw, 34px);
  font-weight: 700;
  line-height: 1.1;
  margin-top: 7px;
}

.modal-sub {
  font-size: 12px;
  line-height: 1.6;
  color: var(--ink-dim);
  margin-top: 8px;
}

.modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
}

/* pause */
.pause-modal .eyebrow {
  justify-content: center;
}

.pause-modal h2 {
  text-align: center;
}

.pause-modal .modal-sub {
  text-align: center;
  margin-bottom: 20px;
}

.pause-progress {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: rgba(255, 235, 200, 0.1);
  border: 1px solid rgba(255, 235, 200, 0.1);
  border-radius: 14px;
  overflow: hidden;
  margin-bottom: 18px;
}

.pause-progress div {
  background: rgba(255, 255, 255, 0.03);
  padding: 12px 10px;
  text-align: center;
}

.pause-progress span {
  display: block;
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.16em;
  color: var(--ink-dim);
  margin-bottom: 4px;
}

.pause-progress b {
  font-family: var(--display);
  font-size: 17px;
  color: var(--gold-hi);
  font-variant-numeric: tabular-nums;
}

.pause-modal .btn {
  margin-bottom: 8px;
}

.pause-toggles {
  display: flex;
  gap: 8px;
  margin-top: 16px;
}

.toggle-pill {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 7px;
  height: 38px;
  padding: 0 11px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.03);
  font-size: 10px;
  font-weight: 700;
  color: var(--ink-dim);
  transition: all 0.2s;
}

.toggle-pill .ico {
  width: 15px;
  height: 15px;
}

.toggle-pill i {
  margin-left: auto;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.2);
}

.toggle-pill.is-on {
  color: var(--ink);
  border-color: rgba(246, 196, 83, 0.28);
  background: rgba(246, 196, 83, 0.08);
}

.toggle-pill.is-on i {
  background: var(--gold);
  box-shadow: 0 0 8px var(--gold);
}

/* result */
.result-modal {
  width: min(640px, 100%);
  padding: 0;
  overflow: hidden;
}

.result-head {
  position: relative;
  padding: 30px 30px 24px;
  text-align: center;
  background:
    radial-gradient(ellipse at 50% 130%, rgba(255, 255, 255, 0.2), transparent 60%),
    linear-gradient(150deg, var(--w1) 0%, var(--w2) 100%);
  color: #1a1207;
  overflow: hidden;
}

.result-head::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(10, 8, 5, 0.18), transparent 35%, rgba(10, 8, 5, 0.48));
  pointer-events: none;
}

.result-head > * {
  position: relative;
  z-index: 2;
}

.result-head .eyebrow {
  justify-content: center;
  color: rgba(26, 18, 7, 0.7);
  font-weight: 800;
}

.result-head h2 {
  font-family: var(--display);
  font-size: clamp(28px, 4vw, 40px);
  font-weight: 800;
  margin-top: 8px;
  color: #fff9ea;
  text-shadow: 0 3px 24px rgba(0, 0, 0, 0.4);
}

.result-sub {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(255, 249, 234, 0.75);
  margin-top: 5px;
}

.big-stars {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin: 16px 0 6px;
}

.big-stars .ico {
  width: 46px;
  height: 46px;
  color: rgba(20, 14, 7, 0.25);
  transition: color 0.3s;
}

.big-stars .ico.lit {
  color: #fff3c4;
  filter: drop-shadow(0 0 16px rgba(255, 236, 160, 0.85)) drop-shadow(0 4px 8px rgba(80, 50, 0, 0.4));
  animation: starPop 0.55s cubic-bezier(0.2, 1.5, 0.4, 1) both;
}

@keyframes starPop {
  0% {
    opacity: 0;
    transform: scale(0.2) rotate(-30deg);
  }
  70% {
    transform: scale(1.18) rotate(4deg);
  }
  100% {
    opacity: 1;
    transform: scale(1) rotate(0);
  }
}

.result-message {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.03em;
  color: rgba(255, 249, 234, 0.8);
  margin-top: 2px;
}

.result-body {
  padding: 22px 30px 26px;
}

.result-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border: 1px solid rgba(255, 235, 200, 0.1);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.025);
  overflow: hidden;
}

.result-stats > div {
  padding: 13px 8px;
  text-align: center;
  position: relative;
}

.result-stats > div + div::before {
  content: '';
  position: absolute;
  left: 0;
  top: 20%;
  bottom: 20%;
  width: 1px;
  background: rgba(255, 235, 200, 0.1);
}

.result-stats span {
  display: block;
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-dim);
  margin-bottom: 4px;
}

.result-stats b {
  font-family: var(--display);
  font-size: 24px;
  font-weight: 700;
  color: var(--gold-hi);
  font-variant-numeric: tabular-nums;
}

.result-stats small {
  display: block;
  font-size: 8px;
  color: var(--ink-dim);
  margin-top: 2px;
}

.result-extra {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-top: 14px;
  min-height: 0;
}

.result-extra .extra-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 10px;
  border-radius: 8px;
  background: rgba(246, 196, 83, 0.08);
  border: 1px solid rgba(246, 196, 83, 0.16);
  font-size: 10px;
  font-weight: 700;
  color: var(--gold);
}

.result-extra .extra-pill .ico {
  width: 13px;
  height: 13px;
}

.result-actions {
  display: flex;
  gap: 8px;
  margin-top: 18px;
}

.result-actions .btn {
  height: 50px;
  border-radius: 13px;
  font-size: 11px;
  letter-spacing: 0.06em;
}

.result-actions #btn-next,
.result-actions [data-primary] {
  flex: 1;
}

.result-modal[data-state='fail'] .result-head {
  background:
    radial-gradient(ellipse at 50% 130%, rgba(255, 120, 80, 0.25), transparent 60%),
    linear-gradient(150deg, #2a0d08, #7c2418 60%, #3c130c);
}

.result-modal[data-state='fail'] .big-stars .ico {
  color: rgba(255, 255, 255, 0.08);
}

.result-modal[data-state='fail'] .result-head h2 {
  color: #ffe2d7;
}

.result-modal[data-state='fail'] #btn-next {
  display: none;
}

.confetti {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  z-index: 1;
}

.confetti i {
  position: absolute;
  top: -12px;
  left: var(--x);
  width: var(--w);
  height: var(--h);
  background: var(--c);
  border-radius: 2px;
  animation: confettiFall var(--d) ease-in var(--delay) both;
  opacity: 0.9;
}

@keyframes confettiFall {
  0% {
    transform: translate3d(0, -20px, 0) rotate(0deg);
    opacity: 0;
  }
  10% {
    opacity: 1;
  }
  100% {
    transform: translate3d(var(--drift), 320px, 0) rotate(var(--rot));
    opacity: 0;
  }
}

/* stage sheet */
.sheet {
  width: min(760px, 100%);
  padding: 0;
}

.sheet-top {
  position: relative;
  padding: 26px 28px 22px;
  background: linear-gradient(140deg, var(--w1), var(--w2));
  color: #160f08;
  overflow: hidden;
  isolation: isolate;
}

.sheet-top::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 85% 130%, rgba(255, 255, 255, 0.3), transparent 55%),
    linear-gradient(180deg, rgba(10, 8, 5, 0.24), transparent 40%, rgba(13, 11, 9, 0.62));
}

.sheet-top > * {
  position: relative;
  z-index: 2;
}

.sheet-top .eyebrow {
  color: rgba(255, 250, 235, 0.8);
}

.sheet-top h2 {
  font-family: var(--display);
  font-size: clamp(26px, 4vw, 40px);
  font-weight: 800;
  color: #fff9ea;
  margin-top: 4px;
  text-shadow: 0 3px 24px rgba(0, 0, 0, 0.35);
}

.sheet-top .sheet-ghost {
  position: absolute;
  right: 24px;
  top: 0;
  z-index: 1;
  font-family: var(--display);
  font-size: 118px;
  line-height: 1;
  font-weight: 800;
  color: rgba(255, 250, 235, 0.25);
  mix-blend-mode: overlay;
  pointer-events: none;
}

.sheet-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 10px;
  flex-wrap: wrap;
}

.sheet-meta span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255, 250, 235, 0.82);
  background: rgba(15, 10, 5, 0.22);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 7px;
  padding: 5px 8px;
}

.sheet-meta .ico {
  width: 12px;
  height: 12px;
}

.sheet-close {
  position: absolute;
  top: 16px;
  right: 16px;
  z-index: 5;
}

.sheet-close.icon-btn {
  background: rgba(15, 10, 6, 0.3);
  border-color: rgba(255, 255, 255, 0.18);
  color: rgba(255, 250, 235, 0.8);
}

.sheet-body {
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.stage-row {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 14px;
  padding: 11px 12px;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.025);
  transition: border-color 0.2s, background 0.2s;
}

.stage-row.is-open {
  border-color: rgba(246, 196, 83, 0.16);
}

.stage-row.is-current {
  border-color: rgba(246, 196, 83, 0.42);
  background: rgba(246, 196, 83, 0.06);
  box-shadow: 0 0 0 1px rgba(246, 196, 83, 0.08), 0 16px 30px -22px rgba(246, 196, 83, 0.6);
}

.stage-row.is-locked {
  opacity: 0.48;
}

.stage-num {
  width: 42px;
  height: 42px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  font-family: var(--display);
  font-size: 17px;
  font-weight: 700;
  color: var(--ink-soft);
  border: 1px solid rgba(255, 235, 200, 0.14);
  background: rgba(255, 255, 255, 0.04);
}

.stage-row.is-current .stage-num,
.stage-row.is-done .stage-num {
  color: #241703;
  background: linear-gradient(160deg, #ffe9a6, #f0b93f);
  border-color: transparent;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7);
}

.stage-info {
  min-width: 0;
}

.stage-info h4 {
  font-family: var(--display);
  font-size: 15px;
  font-weight: 700;
  margin: 0 0 3px;
  letter-spacing: 0.01em;
}

.stage-info p {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  font-size: 9px;
  letter-spacing: 0.03em;
  color: var(--ink-dim);
  font-variant-numeric: tabular-nums;
}

.stage-info p span {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}

.stage-info .ico {
  width: 11px;
  height: 11px;
  color: var(--gold);
  opacity: 0.8;
}

.stage-stars {
  display: flex;
  gap: 2px;
  color: rgba(255, 255, 255, 0.14);
}

.stage-stars .ico {
  width: 15px;
  height: 15px;
}

.stage-stars .ico.lit {
  color: var(--gold);
  filter: drop-shadow(0 0 5px rgba(246, 196, 83, 0.5));
}

.stage-play {
  height: 36px;
  padding: 0 14px;
  border-radius: 9px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  background: linear-gradient(180deg, #ffe9a6, #f2bb45 55%, #d9962b);
  color: #2a1a06;
  transition: filter 0.2s, transform 0.2s;
}

.stage-play .ico {
  width: 12px;
  height: 12px;
}

.stage-play:hover {
  filter: brightness(1.08);
  transform: translateY(-1px);
}

.stage-play.locked {
  background: rgba(255, 255, 255, 0.06);
  color: var(--ink-dim);
  pointer-events: none;
}

.stage-play.locked .ico {
  width: 14px;
  height: 14px;
}

.stage-best {
  font-size: 8px;
  color: var(--ink-dim);
  letter-spacing: 0.04em;
  margin-top: 2px;
}

.sheet-foot {
  padding: 4px 22px 22px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  font-size: 9px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-dim);
}

.sheet-foot b {
  color: var(--gold);
}

/* settings */
.settings-modal .modal-head {
  margin-bottom: 6px;
}

.setting-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 15px 0;
  border-bottom: 1px solid rgba(255, 235, 200, 0.08);
}

.setting-label {
  display: flex;
  align-items: center;
  gap: 12px;
}

.setting-icon {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: rgba(246, 196, 83, 0.07);
  border: 1px solid rgba(246, 196, 83, 0.12);
  color: var(--gold);
  flex: none;
}

.setting-icon .ico {
  width: 17px;
  height: 17px;
}

.setting-label b {
  display: block;
  font-size: 12px;
  font-weight: 700;
}

.setting-label p {
  font-size: 9.5px;
  color: var(--ink-dim);
  margin-top: 2px;
  line-height: 1.4;
}

.switch {
  width: 46px;
  height: 26px;
  border-radius: 20px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(255, 255, 255, 0.06);
  position: relative;
  flex: none;
  transition: background 0.25s, border-color 0.25s;
}

.switch i {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.5);
  transition: transform 0.25s cubic-bezier(0.2, 0.9, 0.3, 1.2), background 0.25s;
}

.switch.is-on {
  background: linear-gradient(90deg, #b6791d, #f6c453);
  border-color: rgba(246, 196, 83, 0.6);
}

.switch.is-on i {
  transform: translateX(20px);
  background: #fffaf0;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
}

.segmented {
  display: flex;
  gap: 3px;
  padding: 3px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  flex: none;
}

.segmented button {
  height: 26px;
  padding: 0 10px;
  border-radius: 7px;
  font-size: 9px;
  font-weight: 700;
  color: var(--ink-dim);
  transition: all 0.2s;
}

.segmented button.is-on {
  background: rgba(246, 196, 83, 0.16);
  color: var(--gold-hi);
}

.danger-zone {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 16px;
  padding: 14px 16px;
  border-radius: 12px;
  border: 1px solid rgba(228, 90, 69, 0.18);
  background: rgba(228, 90, 69, 0.04);
}

.danger-zone b {
  font-size: 11px;
  color: #ffc4b7;
}

.danger-zone p {
  font-size: 9px;
  color: var(--ink-dim);
  margin-top: 2px;
}

.settings-foot {
  margin-top: 16px;
  font-size: 8px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-dim);
  text-align: center;
}

.settings-foot b {
  color: var(--gold);
}

/* toast */
.toast {
  position: fixed;
  z-index: 60;
  left: 50%;
  bottom: 30px;
  transform: translate(-50%, 16px);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 11px 18px;
  border-radius: 12px;
  background: rgba(20, 16, 12, 0.94);
  border: 1px solid rgba(246, 196, 83, 0.28);
  box-shadow: 0 20px 40px -14px rgba(0, 0, 0, 0.9);
  color: var(--ink-soft);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.25s, transform 0.35s cubic-bezier(0.2, 0.9, 0.3, 1.3), visibility 0.25s;
  max-width: min(90vw, 460px);
  text-align: center;
}

.toast.show {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, 0);
}

.toast .ico {
  color: var(--gold);
  width: 16px;
  height: 16px;
}

/* focus */
button:focus-visible,
a:focus-visible {
  outline: 2px solid rgba(246, 196, 83, 0.7);
  outline-offset: 2px;
}

/* ══ responsive ══════════════════════════════════════════════ */
@media (max-width: 1120px) {
  .menu-grid {
    grid-template-columns: minmax(0, 1fr) minmax(300px, 0.78fr);
    gap: 34px;
  }
  .continue-card {
    max-width: 400px;
  }
  .hud-top {
    grid-template-columns: 0.7fr minmax(280px, 1fr) 0.7fr;
  }
}

@media (max-width: 980px) {
  .menu-grid {
    grid-template-columns: 1fr;
    gap: 34px;
    margin: 0 auto;
  }
  .menu-screen {
    padding-top: 96px;
  }
  .hero {
    max-width: 620px;
  }
  .logo-top {
    font-size: clamp(56px, 12vw, 96px);
  }
  .logo-bottom {
    font-size: clamp(72px, 16vw, 124px);
  }
  .continue-card {
    max-width: 560px;
    justify-self: start;
  }
  .menu-footer {
