39:     upgrades: { magnet: 0, heart: 0, value: 0 },
40:     settings: { sound: true, music: true, quality: 'high' },
41:     stats: { runs: 0, cleared: 0, distance: 0, coinsRun: 0 },
42:     createdAt: Date.now(),
43:   }
44: }
45: 
46: let cache = null
47: 
48: export function loadProfile() {
49:   if (cache) return cache
50:   const base = defaults()
51:   try {
52:     const raw = localStorage.getItem(KEY)
53:     if (raw) {
54:       const parsed = JSON.parse(raw)
55:       cache = {
56:         ...base,
57:         ...parsed,
58:         next: { ...base.next, ...(parsed.next || {}) },
59:         upgrades: { ...base.upgrades, ...(parsed.upgrades || {}) },
60:         settings: { ...base.settings, ...(parsed.settings || {}) },
61:         stats: { ...base.stats, ...(parsed.stats || {}) },
62:         stars: parsed.stars || {},
63:         bests: parsed.bests || {},
64:       }
65:     } else {
66:       cache = base
67:     }
68:   } catch {
69:     cache = base
70:   }
71:   return cache
72: }
73: 
74: export function saveProfile(profile = cache) {
75:   cache = profile
76:   try {
77:     localStorage.setItem(KEY, JSON.stringify(profile))
78:   } catch {
79:     /* storage might be unavailable — the run still works */
80:   }
81: }
82: 
83: export function resetProfile() {
84:   cache = defaults()
85:   saveProfile(cache)
86:   return cache
87: }
88: 
89: export function isStageUnlocked(profile, world, stage) {
90:   if (profile.stars[stageKey(world, stage)] > 0) return true
91:   return profile.next.world === world && profile.next.stage === stage
92: }
93: 
94: export function isWorldUnlocked(profile, world) {
95:   if (world <= profile.next.world) return true
96:   for (let s = 1; s <= STAGES_PER_WORLD; s++) {
97:     if (profile.stars[stageKey(world, s)]) return true
98:   }
99:   return false
100: }
101: 
102: export function stageBest(profile, world, stage) {
103:   return profile.bests[stageKey(world, stage)] || null
104: }
105: 
106: export function advanceProgress(profile, world, stage) {
107:   if (world !== profile.next.world || stage !== profile.next.stage) return
108:   let nWorld = world
109:   let nStage = stage + 1
110:   if (nStage > STAGES_PER_WORLD) {
111:     nWorld = world + 1
112:     nStage = 1
113:   }
114:   if (nWorld > WORLDS.length) {
115:     profile.next = { world: WORLDS.length, stage: STAGES_PER_WORLD }
116:     profile.complete = true
117:   } else {
118:     profile.next = { world: nWorld, stage: nStage }
119:   }
120: }
121: 
122: export function recordRun(profile, { world, stage, distance, coins, score, hits, stars, cleared, time }) {
123:   const key = stageKey(world, stage)
124:   const cfg = getStageConfig(world, stage)
125: 
126:   profile.stats.runs += 1
127:   profile.stats.distance += Math.round(distance)
128:   profile.stats.coinsRun += coins
129:   profile.coins += coins
130:   profile.totalCoins += coins
131: 
132:   const prevBest = profile.bests[key]
133:   if (!prevBest || score > prevBest.score) {
134:     profile.bests[key] = { score, distance: Math.round(distance), coins, stars }
135:   }
136: 
137:   if (cleared) {
138:     const prevStars = profile.stars[key] || 0
139:     if (stars > prevStars) profile.stars[key] = stars
140:     if (prevStars === 0) profile.stats.cleared += 1
141:     advanceProgress(profile, world, stage)
142:     profile.lastStage = { world, stage }
143:   }
144: 
145:   saveProfile(profile)
146:   return { best: profile.bests[key], newBest: !prevBest || score > prevBest.score, reward: cleared ? cfg.reward : 0 }
147: }
148: 
149: export function addCoins(profile, amount) {
150:   profile.coins += amount
151:   saveProfile(profile)
152: }
153: 
154: export function totalUpgradeLevel(profile) {
155:   return Object.values(profile.upgrades).reduce((a, b) => a + b, 0)
156: }
157: 
158: export function upgradeCost(type, level) {
159:   const def = UPGRADES[type]
160:   if (!def || level >= def.max) return Infinity
161:   return def.costs[level]
162: }
163: 
164: export function buyUpgrade(profile, type) {
165:   const def = UPGRADES[type]
166:   if (!def) return { ok: false, reason: 'unknown' }
167:   const level = profile.upgrades[type] || 0
168:   if (level >= def.max) return { ok: false, reason: 'max' }
169:   const cost = upgradeCost(type, level)
170:   if (profile.coins < cost) return { ok: false, reason: 'coins' }
171:   profile.coins -= cost
172:   profile.upgrades[type] = level + 1
173:   saveProfile(profile)
174:   return { ok: true, cost, level: level + 1 }
175: }
176: 
177: /** Loadout the run should use, derived from the player's profile. */
178: export function loadout(profile, cfg) {
179:   return {
180:     hearts: cfg.hearts + (profile.upgrades.heart || 0),
181:     magnetTime: cfg.magnetTime + (profile.upgrades.magnet || 0) * 2,
182:     coinValue: 1 + (profile.upgrades.value || 0) * 0.08,
183:   }
184: }
185: 
186: export function nextStageInfo(profile) {
187:   const { world, stage } = profile.next
188:   const cfg = getStageConfig(world, stage)
189:   return {
190:     ...cfg,
191:     worldName: WORLDS[world - 1]?.name || 'The Unknown',
192:     theme: WORLDS[world - 1],
193:     done: !!profile.complete,
194:   }
195: }

