import fs from 'node:fs'
import path from 'node:path'

const root = 'C:/Users/Prasanth/Desktop/opencode project'
const css = fs.readFileSync(path.join(root, 'styles.css'), 'utf8')
const html = fs.readFileSync(path.join(root, 'index.html'), 'utf8')
const js = ['src/main.js', 'src/game.js', 'src/levels.js', 'src/save.js', 'src/audio.js']
  .map((f) => fs.readFileSync(path.join(root, f), 'utf8'))
  .join('\n')
const hay = html + '\n' + js

// All class names referenced in CSS selectors
const cssClasses = new Set()
for (const m of css.matchAll(/\.(-?[_a-zA-Z][\w-]*)/g)) cssClasses.add(m[1])

const unused = [...cssClasses].filter((c) => !new RegExp(`\\b${c.replace(/[-]/g, '\\-')}\\b`).test(hay)).sort()

// IDs referenced in CSS
const cssIds = new Set()
for (const m of css.matchAll(/#([_a-zA-Z][\w-]*)/g)) cssIds.add(m[1])
const usedIds = new Set()
for (const m of (html + js).matchAll(/\bid=["']([^"']+)["']/g)) usedIds.add(m[1])
for (const m of (html + js).matchAll(/(?:getElementById|\\$)\('([^']+)'\)/g)) usedIds.add(m[1])
const unusedIds = [...cssIds].filter((id) => !usedIds.has(id)).sort()

// Keyframes used
const keyframes = [...css.matchAll(/@keyframes\s+([\w-]+)/g)].map((m) => m[1])
const unusedKeyframes = keyframes.filter((k) => {
  const uses = [...css.matchAll(new RegExp(`animation(?:-name)?:[^;{}]*\\b${k}\\b`, 'g'))].length
  return uses === 0
})

// Selectors that may be dead: full rule selector text where every class/id token is unused
console.log(JSON.stringify({ cssClasses: cssClasses.size, unusedClasses: unused, unusedIds, unusedKeyframes }, null, 2))

import fs from 'node:fs'
const css = fs.readFileSync('C:/Users/Prasanth/Desktop/opencode project/styles.css', 'utf8')

// crude top-level + media block parser
const rules = []
let i = 0
const stack = [{ name: 'root', start: 0 }]
while (i < css.length) {
  const open = css.indexOf('{', i)
  if (open === -1) break
  const close = css.indexOf('}', open)
  const prelude = css.slice(i, open).trim()
  if (prelude.startsWith('@')) {
    // nested at-rule: assume it's a wrapper if it contains rules
    rules.push({ ctx: stack.map((s) => s.name).join(' > '), selector: prelude, body: css.slice(open + 1, close).trim() })
  }
  i = close + 1
}

// duplicate selectors (same selector, same context) by scanning blocks with a light parser
function parse(cssText, ctx = []) {
  const out = []
  let i = 0
  while (i < cssText.length) {
    const open = cssText.indexOf('{', i)
    if (open === -1) break
    const close = cssText.indexOf('}', open)
    if (close === -1) break
    const selector = cssText.slice(i, open).trim()
    const body = cssText.slice(open + 1, close)
    if (selector.startsWith('@media') || selector.startsWith('@supports')) {
      out.push(...parse(body, [...ctx, selector]))
    } else if (selector.startsWith('@keyframes')) {
      // skip inner keyframes
    } else {
      const sels = selector.split(',').map((s) => s.trim()).filter(Boolean)
      out.push({ ctx: ctx.join(' / '), sels, selector, body })
    }
    i = close + 1
  }
  return out
}
const parsed = parse(css)

const bySel = new Map()
for (const r of parsed) {
  for (const s of r.sels) {
    const key = r.ctx + '||' + s
    if (!bySel.has(key)) bySel.set(key, [])
    bySel.get(key).push(r)
  }
}
const dup = [...bySel.entries()].filter(([, v]) => v.length > 1).map(([k, v]) => ({
  key: k,
  count: v.length,
  blocks: v.map((r) => r.body.trim().replace(/\s+/g, ' ').slice(0, 220)),
}))
console.log('duplicate selector keys:', dup.length)
for (const d of dup.slice(0, 80)) console.log('\n' + d.key + '  x' + d.count + '\n  ' + d.blocks.join('\n  '))

// repeated declaration lines
const counts = new Map()
for (const r of parsed) {
  if (r.selector.startsWith('@')) continue
  const decls = r.body.split(';').map((s) => s.trim()).filter(Boolean)
  for (const d of decls) counts.set(d, (counts.get(d) || 0) + 1)
}
console.log('\ntop repeated declarations:')
;[...counts.entries()].filter(([, c]) => c > 6).sort((a, b) => b[1] - a[1]).slice(0, 40).forEach(([d, c]) => console.log(String(c).padStart(3), d))

