import * as THREE from 'three'

// ─────────────────────────────────────────────────────────────
//  Shared constants and helpers for the temple run engine.
// ─────────────────────────────────────────────────────────────

export const LANE_X = [-2.35, 0, 2.35]
export const CHUNK_LEN = 32
export const CHUNK_COUNT = 7
export const START_Z = 20
export const PLAYER_H = 1.92
export const SLIDE_H = 0.8
export const GRAVITY = -58
export const JUMP_V = 16.6

export const clamp = (v, a, b) => Math.max(a, Math.min(b, v))
export const lerp = (a, b, t) => a + (b - a) * t
export const damp = (a, b, l, dt) => lerp(a, b, 1 - Math.exp(-l * dt))
export const rand = (a, b) => a + Math.random() * (b - a)
export const randInt = (a, b) => Math.floor(rand(a, b + 1))
export const pick = (arr) => arr[Math.floor(Math.random() * arr.length)]
export const shuffle = (arr) => [...arr].sort(() => Math.random() - 0.5)
export const color = (hex) => new THREE.Color(hex)

/** Soft radial sprite used for glows, dust and blob shadows. */
export function makeGlowTexture(inner = 'rgba(255,255,255,1)', outer = 'rgba(255,255,255,0)') {
  const canvas = document.createElement('canvas')
  canvas.width = canvas.height = 128
  const ctx = canvas.getContext('2d')
  const gradient = ctx.createRadialGradient(64, 64, 2, 64, 64, 62)
  gradient.addColorStop(0, inner)
  gradient.addColorStop(0.35, 'rgba(255,255,255,0.45)')
  gradient.addColorStop(1, outer)
  ctx.fillStyle = gradient
  ctx.fillRect(0, 0, 128, 128)

  const texture = new THREE.CanvasTexture(canvas)
  texture.colorSpace = THREE.SRGBColorSpace
  return texture
}

import * as THREE from 'three'
import { makeGlowTexture, rand } from './core.js'

/**
 * Builds the static world around the track: sky, sun, mountains, temple
 * silhouette, clouds, lights, dust and the two scene groups.
 */
export function buildScenery(game) {
  game.scene = new THREE.Scene()
  game.scene.fog = new THREE.Fog(0xc9a878, 46, 168)

  game.camera = new THREE.PerspectiveCamera(60, 1, 0.1, 900)
  game.camera.position.set(0, 4.7, 9.6)
  game.camera.lookAt(0, 1.7, -16)
  game.camX = 0
  game.camY = 4.7
  game.fov = 60
  game.shake = 0

  buildSky(game)
  buildBackground(game)
  buildClouds(game)
  buildLights(game)

  game.staticGroup = new THREE.Group()
  game.dynamicGroup = new THREE.Group()
  game.scene.add(game.staticGroup, game.dynamicGroup)
  game.glowTex = makeGlowTexture()
  buildDust(game)
}

function buildSky(game) {
  game.skyMat = new THREE.ShaderMaterial({
    uniforms: {
      topColor: { value: new THREE.Color('#1d4e74') },
      bottomColor: { value: new THREE.Color('#ffc46b') },
      sunDir: { value: new THREE.Vector3(0.5, 0.5, -0.7).normalize() },
    },
    vertexShader: /* glsl */ `
      varying vec3 vPos;
      void main() {
        vPos = position;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: /* glsl */ `
      uniform vec3 topColor;
      uniform vec3 bottomColor;
      uniform vec3 sunDir;
      varying vec3 vPos;
      void main() {
        vec3 dir = normalize(vPos);
        float h = clamp(dir.y * 0.5 + 0.5, 0.0, 1.0);
        vec3 c = mix(bottomColor, topColor, pow(h, 1.15));
        float glow = pow(max(dot(dir, normalize(sunDir)), 0.0), 8.0);
        c += vec3(1.0, 0.65, 0.3) * glow * 0.35;
        gl_FragColor = vec4(c, 1.0);
      }
    `,
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
  })

  const sky = new THREE.Mesh(new THREE.SphereGeometry(600, 32, 20), game.skyMat)
  sky.renderOrder = -10
  game.scene.add(sky)

  const glow = makeGlowTexture()
  game.sunSprite = new THREE.Sprite(
    new THREE.SpriteMaterial({
      map: glow,
      color: 0xffd28a,
      transparent: true,
      opacity: 0.95,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      fog: false,
    }),
  )
  game.sunSprite.scale.set(150, 150, 1)
  game.sunSprite.position.set(130, 95, -330)
  game.scene.add(game.sunSprite)
  game.glowTex = glow

  game.apron = new THREE.Mesh(
    new THREE.PlaneGeometry(700, 700),
    new THREE.MeshStandardMaterial({ color: 0x6b573f, roughness: 1, metalness: 0 }),
  )
  game.apron.rotation.x = -Math.PI / 2
  game.apron.position.y = -1.6
  game.apron.receiveShadow = true
  game.scene.add(game.apron)
}

function buildBackground(game) {
  game.bgGroup = new THREE.Group()
  game.bgMats = []

  const mountainColors = [0x6f604d, 0x5a4d3d, 0x4a3f33]
  for (let i = 0; i < 16; i++) {
    const angle = (i / 16) * Math.PI * 2
    const radius = rand(330, 430)
    const height = rand(55, 130)
    const material = new THREE.MeshBasicMaterial({
      color: mountainColors[i % 3],
      fog: false,
      transparent: true,
      opacity: 0.85,
    })
    game.bgMats.push(material)

    const mountain = new THREE.Mesh(new THREE.ConeGeometry(rand(60, 100), height, 5), material)
    mountain.position.set(Math.cos(angle) * radius, height / 2 - 30, Math.sin(angle) * radius - 40)
    mountain.rotation.y = rand(0, Math.PI)
    game.bgGroup.add(mountain)
  }

  game.bgGroup.add(buildDistantTemple(game))
  game.scene.add(game.bgGroup)
}

function buildDistantTemple(game) {
  const material = new THREE.MeshBasicMaterial({ color: 0x3c3026, fog: false, transparent: true, opacity: 0.96 })
  game.bgMats.push(material)

  const temple = new THREE.Group()
  const steps = [
    [220, 26, 60],
    [176, 26, 52],
    [136, 26, 44],
    [100, 26, 36],
    [68, 26, 28],
    [40, 30, 24],
  ]

  let y = -34
  steps.forEach(([width, height, depth], i) => {
    const step = new THREE.Mesh(new THREE.BoxGeometry(width, height, depth), material)
    step.position.y = y + height / 2
    y += height
    temple.add(step)

    if (i === steps.length - 1) {
      const cap = new THREE.Mesh(new THREE.ConeGeometry(width * 0.75, height * 1.6, 4), material)
      cap.position.y = y - 30 + height
      cap.rotation.y = Math.PI / 4
      temple.add(cap)
    }
  })

  const door = new THREE.Mesh(
    new THREE.PlaneGeometry(12, 20),
    new THREE.MeshBasicMaterial({ color: 0xffc45c, fog: false, transparent: true, opacity: 0.55 }),
  )
  door.position.set(0, -34 + 25, 31)
  temple.add(door)
  temple.position.set(0, 0, -395)
  game.temple = temple
  return temple
}

function buildClouds(game) {
  game.clouds = []
  for (let i = 0; i < 7; i++) {
    const cloud = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: game.glowTex,
        color: 0xffffff,
        transparent: true,
        opacity: rand(0.05, 0.13),
        depthWrite: false,
        fog: false,
      }),
    )
    cloud.scale.set(rand(90, 190), rand(24, 44), 1)
    cloud.position.set(rand(-260, 260), rand(45, 105), rand(-380, -220))
    game.scene.add(cloud)
    game.clouds.push(cloud)
  }
}

function buildLights(game) {
  game.hemi = new THREE.HemisphereLight(0xbfe6ff, 0x5b4630, 1.05)
  game.scene.add(game.hemi)

  game.sunLight = new THREE.DirectionalLight(0xfff0cf, 2.4)
  game.sunLight.position.set(14, 24, 10)
  game.sunLight.castShadow = true
  game.sunLight.shadow.mapSize.set(2048, 2048)
  game.sunLight.shadow.camera.left = -20
  game.sunLight.shadow.camera.right = 20
  game.sunLight.shadow.camera.top = 24
  game.sunLight.shadow.camera.bottom = -10
  game.sunLight.shadow.camera.near = 1
  game.sunLight.shadow.camera.far = 80
  game.sunLight.shadow.bias = -0.0004
  game.sunLight.shadow.normalBias = 0.02
  game.sunLight.target.position.set(0, 0, -6)
  game.scene.add(game.sunLight, game.sunLight.target)

  game.accentLight = new THREE.PointLight(0xffc45c, 26, 42, 1.8)
  game.accentLight.position.set(0, 4.5, -8)
  game.scene.add(game.accentLight)

  game.rimLight = new THREE.DirectionalLight(0x9fd8ff, 0.7)
  game.rimLight.position.set(-10, 8, -18)
  game.scene.add(game.rimLight)
}

function buildDust(game) {
  const count = 260
  const positions = new Float32Array(count * 3)
  const seeds = new Float32Array(count)
  for (let i = 0; i < count; i++) {
    positions[i * 3] = rand(-20, 20)
    positions[i * 3 + 1] = rand(0.2, 12)
    positions[i * 3 + 2] = rand(-120, 12)
    seeds[i] = rand(0, Math.PI * 2)
  }
  game.dustSeeds = seeds

  const geometry = new THREE.BufferGeometry()
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3))
  game.dust = new THREE.Points(
    geometry,
    new THREE.PointsMaterial({
      color: 0xffe6b0,
      size: 0.16,
      map: game.glowTex,
      transparent: true,
      opacity: 0.5,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      sizeAttenuation: true,
    }),
  )
  game.dust.frustumCulled = false
  game.scene.add(game.dust)
}

import * as THREE from 'three'
import { CHUNK_COUNT, CHUNK_LEN, START_Z, rand } from './core.js'

/** Creates the reusable geometry, the chunk groups and the first track. */
export function initTrack(game) {
  game.floorGeo = new THREE.BoxGeometry(10.6, 0.7, CHUNK_LEN)
  game.sideGeo = new THREE.BoxGeometry(3.2, 0.5, CHUNK_LEN)
  game.laneGeo = new THREE.BoxGeometry(0.05, 0.02, CHUNK_LEN)
  game.pillarGeo = new THREE.CylinderGeometry(0.42, 0.54, 1, 7)
  game.capGeo = new THREE.BoxGeometry(1.2, 0.26, 1.2)
  game.postGeo = new THREE.CylinderGeometry(0.09, 0.12, 1, 6)
  game.trunkGeo = new THREE.CylinderGeometry(0.16, 0.26, 1, 6)
  game.leafGeo = new THREE.ConeGeometry(1, 1, 6)

  for (let i = 0; i < CHUNK_COUNT; i++) {
    const group = new THREE.Group()
    group.userData.index = i
    game.staticGroup.add(group)
    game.chunks.push(group)
  }
  buildTrack(game)
}

export function buildTrack(game) {
  game.flames.length = 0
  game.chunks.forEach((group, i) => {
    group.clear()
    group.position.set(0, 0, START_Z - i * CHUNK_LEN)
    buildChunk(game, group, i)
  })
}

function buildChunk(game, group, index) {
  const M = game.materials

  const floor = new THREE.Mesh(game.floorGeo, M.floor)
  floor.position.y = -0.35
  floor.receiveShadow = true
  group.add(floor)

  for (const x of [-6.8, 6.8]) {
    const ledge = new THREE.Mesh(game.sideGeo, M.stoneDark)
    ledge.position.set(x, -0.5, 0)
    ledge.receiveShadow = true
    group.add(ledge)
  }

  const curbGeo = new THREE.BoxGeometry(0.24, 0.16, CHUNK_LEN)
  for (const x of [-5.15, 5.15]) {
    const curb = new THREE.Mesh(curbGeo, M.gold)
    curb.position.set(x, 0.08, 0)
    curb.receiveShadow = true
    group.add(curb)
  }

  for (const x of [-1.175, 1.175]) {
    const lane = new THREE.Mesh(game.laneGeo, M.stoneDark)
    lane.position.set(x, 0.005, 0)
    group.add(lane)
  }

  buildPillars(game, group, index)
  buildArch(game, group, index)
  buildFoliage(game, group)
  buildRubble(game, group)
}

function buildPillars(game, group, index) {
  const M = game.materials
  const dashPattern = [1, 1, 0, 1, 0, 1, 1, 0]

  for (let s = 0; s < 4; s++) {
    const z = -CHUNK_LEN / 2 + 4 + s * 8
    for (const side of [-1, 1]) {
      if (dashPattern[(s + index + (side > 0 ? 3 : 0)) % dashPattern.length] === 0) continue

      const broken = Math.random() < 0.22
      const height = broken ? rand(1.2, 2.4) : rand(4.2, 6.4)
      const x = side * rand(6.3, 7.1)
      const pillar = new THREE.Mesh(game.pillarGeo, M.stone)
      pillar.scale.y = height
      pillar.position.set(x, height / 2 - 0.2, z + rand(-0.5, 0.5))
      pillar.rotation.y = rand(0, Math.PI)
      pillar.castShadow = true
      pillar.receiveShadow = true
      group.add(pillar)

      const cap = new THREE.Mesh(game.capGeo, M.stoneDark)
      cap.position.set(x, height - 0.2, pillar.position.z)
      cap.rotation.y = pillar.rotation.y
      cap.scale.setScalar(rand(0.85, 1.2))
      cap.castShadow = true
      group.add(cap)

      if (!broken && (s + index) % 2 === 0) buildTorch(game, group, x, pillar.position.z, side)
    }
  }
}

function buildTorch(game, group, x, z, side) {
  const M = game.materials
  const post = new THREE.Mesh(game.postGeo, M.wood)
  post.scale.y = 0.9
  post.position.set(x - side * 0.75, 2.2, z)
  group.add(post)

  const bowl = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.14, 0.24, 8), M.gold)
  bowl.position.set(post.position.x, 2.72, post.position.z)
  group.add(bowl)

  const flame = new THREE.Mesh(new THREE.IcosahedronGeometry(0.23, 0), M.flame)
  flame.position.set(post.position.x, 2.98, post.position.z)
  flame.scale.set(1, 1.5, 1)
  flame.userData.phase = rand(0, 10)
  group.add(flame)
  game.flames.push(flame)

  const glow = new THREE.Sprite(M.glow.clone())
  glow.position.set(flame.position.x, 3.02, flame.position.z)
  glow.scale.set(2.6, 2.6, 1)
  group.add(glow)
}

function buildArch(game, group, index) {
  if (index % 3 !== 1 && Math.random() >= 0.25) return

  const M = game.materials
  const z = -CHUNK_LEN / 2 + rand(8, 24)
  const height = 6.4

  for (const side of [-1, 1]) {
    const pillar = new THREE.Mesh(game.pillarGeo, M.stoneDark)
    pillar.scale.y = height
    pillar.position.set(side * 5.6, height / 2 - 0.2, z)
    pillar.castShadow = true
    group.add(pillar)
  }

  const lintel = new THREE.Mesh(new THREE.BoxGeometry(12.4, 0.8, 1.1), M.stone)
  lintel.position.set(0, height - 0.2, z)
  lintel.castShadow = true
  group.add(lintel)

  const trim = new THREE.Mesh(new THREE.BoxGeometry(12.6, 0.14, 1.24), M.gold)
  trim.position.set(0, height - 0.66, z)
  group.add(trim)

  for (let v = 0; v < 4; v++) {
    if (Math.random() < 0.5) continue
    const length = rand(0.8, 2.6)
    const vine = new THREE.Mesh(new THREE.BoxGeometry(0.06, length, 0.06), M.foliage2)
    vine.position.set(rand(-4.6, 4.6), height - 0.6 - length / 2, z + 0.2)
    group.add(vine)
  }

  const banner = new THREE.Mesh(new THREE.PlaneGeometry(1.1, 2.4), M.banner)
  banner.position.set(rand(-3.6, 3.6), height - 1.9, z + 0.5)
  group.add(banner)
}

function buildFoliage(game, group) {
  const M = game.materials
  for (let t = 0; t < 3; t++) {
    const side = Math.random() < 0.5 ? -1 : 1
    const x = side * rand(8.6, 13.5)
    const z = rand(-CHUNK_LEN / 2 + 2, CHUNK_LEN / 2 - 2)
    const trunkHeight = rand(2.4, 4.6)

    const trunk = new THREE.Mesh(game.trunkGeo, M.wood)
    trunk.scale.y = trunkHeight
    trunk.position.set(x, trunkHeight / 2 - 1.2, z)
    trunk.castShadow = true
    group.add(trunk)

    const leaves = new THREE.Mesh(game.leafGeo, Math.random() < 0.5 ? M.foliage : M.foliage2)
    leaves.scale.set(rand(1.4, 2.4), rand(2.4, 4.2), rand(1.4, 2.4))
    leaves.position.set(x + rand(-0.4, 0.4), trunkHeight - 0.4, z)
    leaves.rotation.y = rand(0, Math.PI)
    leaves.castShadow = true
    group.add(leaves)
  }
}

function buildRubble(game, group) {
  for (let r = 0; r < 4; r++) {
    const rubble = new THREE.Mesh(
      new THREE.BoxGeometry(rand(0.3, 0.8), rand(0.2, 0.5), rand(0.3, 0.9)),
      game.materials.stoneDark,
    )
    const side = Math.random() < 0.5 ? -1 : 1
    rubble.position.set(side * rand(6.1, 9.6), 0.05, rand(-14, 14))
    rubble.rotation.y = rand(0, Math.PI)
    rubble.castShadow = true
    group.add(rubble)
  }
}

/** Finish gate — built once and reused for every stage. */
export function buildGate(game) {
  const group = new THREE.Group()
  const M = game.materials

  const pillarGeo = new THREE.BoxGeometry(0.9, 7.2, 0.9)
  for (const side of [-1, 1]) {
    const pillar = new THREE.Mesh(pillarGeo, M.stone)
    pillar.position.set(side * 4.5, 3.2, 0)
    pillar.castShadow = true
    group.add(pillar)

    const cap = new THREE.Mesh(new THREE.BoxGeometry(1.2, 0.35, 1.2), M.gold)
    cap.position.set(side * 4.5, 6.9, 0)
    group.add(cap)

    const base = new THREE.Mesh(new THREE.BoxGeometry(1.4, 0.5, 1.4), M.stoneDark)
    base.position.set(side * 4.5, 0.15, 0)
    group.add(base)
  }

  const lintel = new THREE.Mesh(new THREE.BoxGeometry(10.4, 1.1, 1.1), M.stoneDark)
  lintel.position.y = 7.4
  lintel.castShadow = true
  group.add(lintel)

  const trim = new THREE.Mesh(new THREE.BoxGeometry(10.6, 0.2, 1.3), M.gold)
  trim.position.y = 8.05
  group.add(trim)

  const crest = new THREE.Mesh(new THREE.ConeGeometry(1.1, 1.2, 4), M.gold)
  crest.position.y = 8.7
  crest.rotation.y = Math.PI / 4
  group.add(crest)

  game.gatePortal = new THREE.Mesh(
    new THREE.PlaneGeometry(8.2, 6.6),
    new THREE.MeshBasicMaterial({
      color: 0xffd36b,
      transparent: true,
      opacity: 0.35,
      blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide,
      depthWrite: false,
    }),
  )
  game.gatePortal.position.y = 3.6
  group.add(game.gatePortal)

  game.gateRing = new THREE.Mesh(
    new THREE.TorusGeometry(2.4, 0.06, 6, 48),
    new THREE.MeshBasicMaterial({
      color: 0xffe8a8,
      transparent: true,
      opacity: 0.8,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    }),
  )
  game.gateRing.position.y = 3.6
  group.add(game.gateRing)

  const glow = new THREE.Sprite(M.glow.clone())
  glow.position.set(0, 4, 0)
  glow.scale.set(18, 18, 1)
  group.add(glow)

  group.visible = false
  game.gate = group
  game.dynamicGroup.add(group)
}

import * as THREE from 'three'
import { makeGlowTexture } from './core.js'

const material = (color, roughness = 0.85, extra = {}) =>
  new THREE.MeshStandardMaterial({ color, roughness, ...extra })

/** Builds the runner, scarf, satchel relic, blob shadow and pickup FX. */
export function buildPlayer(game) {
  const skin = material(0xd39a67, 0.75)
  const shirt = material(0x25786c, 0.8)
  const shirtDark = material(0x185a51, 0.85)
  const pants = material(0x57432f, 0.9)
  const leather = material(0x7a4b26, 0.85)
  const scarf = material(0xe0512f, 0.8)
  const hair = material(0x27170e, 0.95)
  const boot = material(0x342417, 0.95)
  const eye = new THREE.MeshBasicMaterial({ color: 0x1b1108 })
  const M = { skin, shirt, shirtDark, pants, leather, scarf, hair, boot, gold: game.materials.gold }

  game.player = new THREE.Group()
  game.player.position.set(0, 0, 0)
  game.scene.add(game.player)

  const rig = new THREE.Group()
  game.player.add(rig)
  game.rig = rig

  buildTorso(game, rig, M)
  buildHead(game, rig, M, eye)
  buildScarf(rig, scarf)
  buildSatchel(game, rig, leather)
  game.arms = [-1, 1].map((side) => buildArm(rig, side, M))
  game.legs = [-1, 1].map((side) => buildLeg(rig, side, M))
  buildPlayerEffects(game)
}

function buildTorso(game, rig, M) {
  const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.28, 0.42, 4, 12), M.shirt)
  torso.position.y = 1.13
  torso.castShadow = true
  rig.add(torso)

  const belt = new THREE.Mesh(new THREE.CylinderGeometry(0.295, 0.295, 0.11, 12), M.leather)
  belt.position.y = 0.86
  rig.add(belt)

  const buckle = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.11, 0.05), M.gold)
  buckle.position.set(0, 0.86, -0.29)
  rig.add(buckle)

  const chest = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.26, 0.28, 12), M.shirtDark)
  chest.position.y = 1.34
  rig.add(chest)
}

function buildHead(game, rig, M, eye) {
  game.head = new THREE.Group()
  game.head.position.y = 1.62
  rig.add(game.head)

  const skull = new THREE.Mesh(new THREE.SphereGeometry(0.225, 16, 12), M.skin)
  skull.castShadow = true
  game.head.add(skull)

  const hairCap = new THREE.Mesh(
    new THREE.SphereGeometry(0.235, 16, 9, 0, Math.PI * 2, 0, Math.PI * 0.58),
    M.hair,
  )
  hairCap.position.y = 0.03
  hairCap.rotation.x = -0.18
  game.head.add(hairCap)

  const band = new THREE.Mesh(new THREE.TorusGeometry(0.228, 0.032, 8, 20), M.scarf)
  band.rotation.x = Math.PI / 2
  band.position.y = 0.055
  game.head.add(band)

  const nose = new THREE.Mesh(new THREE.ConeGeometry(0.045, 0.11, 6), M.skin)
  nose.rotation.x = -Math.PI / 2
  nose.position.set(0, -0.02, -0.22)
  game.head.add(nose)

  for (const side of [-1, 1]) {
    const e = new THREE.Mesh(new THREE.SphereGeometry(0.026, 8, 8), eye)
    e.position.set(side * 0.078, 0.02, -0.2)
    game.head.add(e)
  }
}

function buildScarf(rig, scarf) {
  const group = new THREE.Group()
  group.position.set(0, 1.45, 0.16)
  rig.add(group)

  const links = []
  for (let i = 0; i < 4; i++) {
    const link = new THREE.Mesh(new THREE.BoxGeometry(0.16 - i * 0.022, 0.05, 0.2), scarf)
    link.position.set(0, -i * 0.035, 0.12 + i * 0.17)
    link.rotation.x = -0.1 * i
    group.add(link)
    links.push(link)
  }
  group.userData.links = links
  rig.userData.scarf = group
}

function buildSatchel(game, rig, leather) {
  const bag = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.44, 0.24), leather)
  bag.position.set(0, 1.16, 0.29)
  bag.rotation.x = 0.08
  bag.castShadow = true
  rig.add(bag)

  const strap = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.5, 0.06), game.materials.gold)
  strap.position.set(0.16, 1.28, 0.06)
