  hand.position.y = -0.63
  group.add(hand)

  const wristband = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.075, 0.05, 8), M.scarf)
  wristband.position.y = -0.55
  group.add(wristband)
