    grounded: true,
    slideAmt: 0,
    sliding: 0,
    runPhase: 0,
    laneIndex: 1,
    playerX: 0,
    lean: 0,
    stumble: 0,
    invuln: 0,
  })
  game.player.position.y = 0
}

