const info = await tools.browser.evaluate({
  tabID: tab.id,
  script: `(() => {
    const boot = document.getElementById('boot');
    const canvas = document.getElementById('scene');
    return {
      title: document.title,
      readyState: document.readyState,
      bootDisplay: boot ? getComputedStyle(boot).display : 'missing',
      canvas: canvas ? { w: canvas.width, h: canvas.height } : null,
      view: document.getElementById('app')?.dataset.view,
      activeScreen: document.querySelector('.screen.is-active')?.id || null,
      hasWebGL: !!canvas?.getContext('webgl2') || !!canvas?.getContext('webgl'),
    };
  })()`,
})
return { tabID: tab.id, pageLoaded, loadError: tab.loadError || null, errors: errors.messages, info: info.value }

