/* ══ login ═══════════════════════════════════════════════════ */
.login-screen {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: clamp(18px, 6vw, 64px) clamp(16px, 6vw, 72px) clamp(28px, 8vw, 72px);
  background:
    radial-gradient(ellipse at 50% 0%, rgba(246, 196, 83, 0.14), transparent 58%),
    radial-gradient(ellipse at 50% 100%, rgba(120, 80, 28, 0.12), transparent 62%),
    radial-gradient(ellipse at 12% 18%, rgba(101, 230, 255, 0.06), transparent 40%),
    #080604;
  overflow-y: auto;
}

.login-wrap {
  width: min(1180px, 100%);
  display: flex;
  flex-direction: column;
  gap: clamp(20px, 4vw, 38px);
}

.login-head {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.login-brand {
  display: flex;
  align-items: center;
  gap: 16px;
}

.login-title {
  font-family: var(--display);
  font-weight: 800;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  font-size: clamp(28px, 7vw, 72px);
}

.login-title em {
  color: var(--gold);
  font-style: normal;
}

.login-sub {
  max-width: 780px;
  color: var(--ink-dim);
  line-height: 1.8;
  font-size: clamp(12px, 1.2vw, 15px);
}

.login-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(280px, 0.8fr);
  gap: clamp(16px, 4vw, 28px);
  align-items: start;
}

.login-panel {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: clamp(20px, 4vw, 32px);
  border-radius: 28px;
  background:
    radial-gradient(ellipse at 20% -10%, rgba(246, 196, 83, 0.12), transparent 48%),
    linear-gradient(180deg, rgba(32, 26, 20, 0.96), rgba(14, 12, 9, 0.98));
  border: 1px solid rgba(255, 235, 200, 0.16);
  box-shadow: var(--shadow);
  overflow: hidden;
}

.login-panel::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse at 50% 120%, rgba(246, 196, 83, 0.08), transparent 60%);
}

.login-panel > * {
  position: relative;
  z-index: 1;
}

.login-panel-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.login-panel-head h2 {
  font-family: var(--display);
  font-size: clamp(20px, 3vw, 28px);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.login-panel-head p {
  margin-top: 6px;
  color: var(--ink-dim);
  font-size: 12px;
}

.login-badge {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px solid rgba(74, 217, 164, 0.4);
  color: var(--jade);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.16em;
}

.login-badge .ico {
  width: 14px;
  height: 14px;
}

.login-continue {
  display: flex;
}

.login-continue-btn {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 18px;
  border-radius: 18px;
  background: linear-gradient(90deg, rgba(246, 196, 83, 0.22), transparent);
  border: 1px solid rgba(246, 196, 83, 0.4);
  text-align: left;
}

.login-continue-btn .ico {
  margin-left: auto;
  color: var(--gold);
}

.lc-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: radial-gradient(circle, #ffe9a9, #f6c453);
  color: #2a1a06;
  font-size: 22px;
}

.lc-copy {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.lc-copy small {
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--gold);
}

.lc-copy b {
  font-size: 16px;
}

.login-accounts {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.login-account {
  width: 100%;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 14px;
  padding: 12px 16px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.01);
  border: 1px solid rgba(255, 235, 200, 0.1);
  text-align: left;
  transition: border-color 0.2s, background 0.2s, transform 0.2s;
}

.login-account:hover {
  border-color: rgba(246, 196, 83, 0.4);
  background: rgba(246, 196, 83, 0.08);
  transform: translateX(4px);
}

.login-account.is-current {
  border-color: rgba(246, 196, 83, 0.5);
  box-shadow: inset 0 0 0 1px rgba(246, 196, 83, 0.18);
}

.la-avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(150deg, #ffe9a9, #e8a72e);
  color: #2a1a06;
  font-size: 20px;
}

.la-main {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.la-top {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.la-top b {
  font-size: 15px;
}

.la-tag {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  font-size: 8px;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--ink-dim);
}

.la-tag-live {
  border-color: rgba(74, 217, 164, 0.5);
  color: var(--jade);
}

.la-tag .ico {
  width: 12px;
  height: 12px;
}

.la-stats {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--ink-soft);
}

.la-stats .ico {
  width: 14px;
  height: 14px;
  color: var(--gold);
}

.la-main small {
  font-size: 10px;
  color: var(--ink-dim);
}

.la-go {
  color: var(--gold);
}

.login-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 10px;
  padding: 18px;
  border-radius: 18px;
  border: 1px dashed rgba(255, 235, 200, 0.18);
}

.login-empty-icon {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(246, 196, 83, 0.12);
  color: var(--gold);
}

.login-empty b {
  font-size: 16px;
}

.login-empty p {
  max-width: 320px;
  color: var(--ink-dim);
  line-height: 1.7;
}

.login-guest {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 14px;
  padding: 14px 18px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.01);
  border: 1px solid rgba(255, 235, 200, 0.12);
  text-align: left;
}

.lg-icon {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.04);
  color: var(--gold);
}

.lg-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.lg-copy small {
  color: var(--ink-dim);
}

.login-note {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--ink-dim);
  font-size: 11px;
}

.login-note .ico {
  width: 16px;
  height: 16px;
  color: var(--gold);
}

.field {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.field span {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--ink-dim);
}

.field span i {
  font-style: normal;
  color: rgba(248, 240, 221, 0.4);
}

.field input {
  height: 52px;
  border-radius: 14px;
  border: 1px solid rgba(255, 235, 200, 0.16);
  background: rgba(255, 255, 255, 0.01);
  color: var(--ink);
  padding: 0 16px;
  font-size: 14px;
}

.field input::placeholder {
  color: rgba(147, 130, 106, 0.8);
}

.avatar-picker {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.avatar-option {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid rgba(255, 235, 200, 0.12);
  font-size: 20px;
}

.avatar-option.is-on {
  border-color: rgba(246, 196, 83, 0.6);
  box-shadow: 0 0 0 4px rgba(246, 196, 83, 0.1);
}

.field-help {
  color: var(--ink-dim);
  font-size: 11px;
  line-height: 1.7;
}

.login-error {
  color: #ffb49a;
  font-size: 11px;
  min-height: 16px;
}

.login-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  color: var(--ink-dim);
}

.login-foot p {
  display: flex;
  align-items: center;
  gap: 10px;
}

.login-foot .ico {
  color: var(--gold);
}

.login-pin {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(5, 4, 3, 0.78);
  backdrop-filter: blur(10px);
  padding: 18px;
  z-index: 50;
}

.login-pin[hidden] {
  display: none;
}

.login-pin-card {
  width: min(360px, 100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 12px;
  padding: 30px 26px;
  border-radius: 26px;
  background: radial-gradient(ellipse at 50% -10%, rgba(246, 196, 83, 0.16), transparent 54%), linear-gradient(180deg, rgba(30, 25, 19, 0.98), rgba(13, 11, 9, 0.98));
  border: 1px solid rgba(255, 235, 200, 0.18);
  box-shadow: var(--shadow);
}

.login-pin-avatar {
  width: 68px;
  height: 68px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(150deg, #ffe9a9, #f6c453);
  color: #2a1a06;
  font-size: 34px;
}

.login-pin-sub {
  color: var(--ink-dim);
}

.pin-input {
  width: 220px;
  height: 56px;
  border-radius: 16px;
  border: 1px solid rgba(255, 235, 200, 0.2);
  background: transparent;
  color: var(--ink);
  text-align: center;
  letter-spacing: 1.2em;
  font-size: 20px;
}

/* ══ account chip / account modal ═════════════════════════════ */
.account-chip {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 38px;
  padding: 0 14px 0 6px;
  border-radius: 999px;
  background: rgba(16, 13, 10, 0.6);
  border: 1px solid rgba(255, 235, 200, 0.16);
  backdrop-filter: blur(10px);
  pointer-events: auto;
}

.account-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(150deg, #ffe9a9, #f6c453);
  color: #2a1a06;
  font-size: 16px;
}

.account-avatar-sm {
  width: 36px;
  height: 36px;
  font-size: 18px;
}

.account-avatar-xl {
  width: 64px;
  height: 64px;
  font-size: 32px;
}

.account-name {
  font-size: 12px;
}

.account-modal {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.account-hero {
  display: flex;
  align-items: center;
  gap: 16px;
}

.account-hero h3 {
  font-family: var(--display);
  font-size: 22px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.account-hero p {
  color: var(--ink-dim);
}

.account-stat-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.account-stat-grid > div {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 14px 10px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.01);
  border: 1px solid rgba(255, 235, 200, 0.1);
}

.account-stat-grid span {
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--ink-dim);
}

.account-stat-grid b {
  display: flex;
  align-items: baseline;
  gap: 4px;
  font-size: 22px;
}

.account-stat-grid small {
  font-size: 12px;
  color: var(--ink-dim);
}

.account-next {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 18px;
  border-radius: 18px;
  background: linear-gradient(90deg, rgba(246, 196, 83, 0.16), transparent);
  border: 1px solid rgba(246, 196, 83, 0.32);
}

.account-next-icon {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--gold);
}

.account-tip {
  color: var(--ink-dim);
  line-height: 1.8;
}

.account-actions {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.account-foot {
  text-align: center;
  color: var(--ink-dim);
  font-size: 11px;
}

.setting-runner {
  align-items: center;
}

.setting-runner .btn-sm {
  height: 38px;
  padding: 0 14px;
}

/* ══ tutorial ═════════════════════════════════════════════════ */
.tutorial-modal {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.tutorial-close {
  position: absolute;
  top: 18px;
  right: 18px;
}

.tutorial-visual {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
  padding: 26px 18px;
  border-radius: 22px;
  background: radial-gradient(ellipse at 50% 0%, rgba(246, 196, 83, 0.12), transparent 60%), rgba(255, 255, 255, 0.01);
  border: 1px solid rgba(255, 235, 200, 0.12);
}

.tut-lane-demo {
  display: flex;
  gap: 10px;
}

.tut-lane {
  width: 86px;
  height: 110px;
  border-radius: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: 12px 0;
  background: rgba(255, 255, 255, 0.01);
  border: 1px solid rgba(255, 235, 200, 0.1);
  color: var(--ink-dim);
}

.tut-lane.is-active {
  border-color: rgba(246, 196, 83, 0.6);
  color: var(--gold);
}

.tut-runner {
  width: 26px;
  height: 40px;
  border-radius: 10px 10px 6px 6px;
  background: linear-gradient(180deg, #ffe9a9, #f6c453);
  box-shadow: 0 10px 20px -10px rgba(246, 196, 83, 0.8);
}

.tut-keys {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--ink-dim);
}

.tut-actions-demo {
  display: flex;
  gap: 16px;
}

.tut-action {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}

.tut-arrow {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(18, 15, 12, 0.7);
  border: 1px solid rgba(255, 235, 200, 0.18);
}

.tut-arrow.is-up .ico { color: var(--gold); }
.tut-arrow.is-down .ico { transform: rotate(180deg); }

.tut-guide-demo {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px 24px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(246, 196, 83, 0.2), transparent);
  border: 1px solid rgba(246, 196, 83, 0.4);
}

.tut-tip {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--ink-dim);
}

.tut-tip .ico {
  color: var(--gold);
}

.tutorial-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
}

.tutorial-dots i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.2);
}

.tutorial-dots i.is-on {
  background: var(--gold);
  box-shadow: 0 0 0 6px rgba(246, 196, 83, 0.12);
}

.tutorial-actions {
  display: flex;
  gap: 12px;
}

.tutorial-actions .btn {
  flex: 1;
}

.tutorial-foot {
  text-align: center;
  color: var(--ink-dim);
}

/* ══ HUD guide + lane ═════════════════════════════════════════ */
.hud-guide {
  position: absolute;
  top: max(90px, env(safe-area-inset-top) + 70px);
  left: 50%;
  transform: translateX(-50%) translateY(-12px);
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 22px 10px 12px;
  border-radius: 999px;
  background: radial-gradient(ellipse at 20% 50%, rgba(246, 196, 83, 0.22), transparent 60%), rgba(16, 13, 10, 0.8);
  border: 1px solid rgba(246, 196, 83, 0.5);
  backdrop-filter: blur(12px);
  box-shadow: 0 30px 60px -30px rgba(246, 196, 83, 0.6);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.25s, transform 0.25s, visibility 0.25s;
  pointer-events: none;
}

.hud-guide.is-on {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.hud-guide.is-urgent {
  animation: guidePulse 0.8s ease-in-out infinite alternate;
}

@keyframes guidePulse {
  from { box-shadow: 0 30px 60px -30px rgba(246, 196, 83, 0.6); }
  to { box-shadow: 0 30px 70px -20px rgba(246, 196, 83, 0.9); }
}

.guide-arrow {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(150deg, #ffe9a9, #f6c453);
  color: #2a1a06;
}

.guide-copy {
  display: flex;
  flex-direction: column;
}

.guide-kicker {
  font-size: 8px;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: rgba(248, 240, 221, 0.6);
}

.guide-copy b {
  font-size: 16px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.guide-copy small {
  font-size: 10px;
  color: var(--ink-dim);
}

.lane-hud {
  position: absolute;
  left: 50%;
  bottom: calc(max(16px, env(safe-area-inset-bottom)) + 96px);
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  opacity: 0.8;
  pointer-events: none;
}

.lane-hud-label {
  font-size: 8px;
  text-transform: uppercase;
  letter-spacing: 0.24em;
  color: var(--ink-dim);
}

.lane-hud-track {
  display: flex;
  gap: 8px;
}

.lane-hud-track i {
  width: 44px;
  height: 6px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.16);
}

.lane-hud-track i.is-on {
  background: linear-gradient(90deg, #ffe9a9, #f6c453);
  box-shadow: 0 0 0 4px rgba(246, 196, 83, 0.12);
}

.touch-btn.is-hint {
  box-shadow: 0 0 0 4px rgba(246, 196, 83, 0.18), 0 10px 24px -10px rgba(0, 0, 0, 0.8);
  border-color: rgba(246, 196, 83, 0.6);
}

.help-guide-card {
  position: relative;
  overflow: hidden;
}

.help-badge {
  position: absolute;
  top: 16px;
  right: 16px;
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(246, 196, 83, 0.22);
  border: 1px solid rgba(246, 196, 83, 0.4);
  font-size: 8px;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--gold);
}

.help-guide-card .link-btn {
  margin-top: 12px;
}

/* ══ responsive additions ═════════════════════════════════════ */
@media (max-width: 980px) {
  .login-grid {
    grid-template-columns: 1fr;
  }
  .account-stat-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 720px) {
  .login-screen {
    padding-top: 86px;
  }
  .login-brand {
    align-items: flex-start;
  }
  .login-title {
    letter-spacing: 0.14em;
  }
  .login-panel {
    border-radius: 22px;
  }
  .tutorial-actions {
    flex-direction: column;
  }
  .hud-guide {
    top: max(76px, env(safe-area-inset-top) + 58px);
    padding: 8px 16px 8px 10px;
    gap: 10px;
  }
  .guide-arrow {
    width: 38px;
    height: 38px;
  }
  .guide-copy b {
    font-size: 14px;
  }
}

@media (max-width: 420px) {
  .account-chip {
    padding: 0 10px 0 6px;
  }
  .account-name {
    display: none;
  }
  .la-tag {
    display: none;
  }
  .lane-hud-track i {
    width: 34px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  .embers {
    display: none;
  }
  .hud-guide.is-urgent {
    animation: none;
  }
}

